/* DAWAH X — ahmad, অধ্যায় 68 · খণ্ড 68 · 200 টি হাদিস · উৎস: https://github.com/elyabany/Hadith */
window.HADITH_DATA['ahmad'][68]=[[13401,13401,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏رَأَى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رَجُلًا يَسُوقُ ‏ ‏بَدَنَةً ‏ ‏قَالَ ‏ ‏ارْكَبْهَا قَالَ إِنَّهَا ‏ ‏بَدَنَةٌ ‏ ‏قَالَ ارْكَبْهَا ‏ ‏وَيْحَكَ ‏","","",""],[13402,13402,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَلَدِهِ وَوَالِدِهِ وَالنَّاسِ أَجْمَعِينَ ‏","","",""],[13403,13403,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثٌ مَنْ كُنَّ فِيهِ وَجَدَ طَعْمَ الْإِيمَانِ مَنْ كَانَ يُحِبُّ الْمَرْءَ لَا يُحِبُّهُ إِلَّا لِلَّهِ عَزَّ وَجَلَّ وَمَنْ كَانَ اللَّهُ وَرَسُولُهُ أَحَبَّ إِلَيْهِ مِمَّا سِوَاهُمَا وَمَنْ كَانَ أَنْ يُلْقَى فِي النَّارِ أَحَبَّ إِلَيْهِ مِنْ أَنْ يَرْجِعَ فِي الْكُفْرِ بَعْدَ إِذْ أَنْقَذَهُ اللَّهُ مِنْهُ ‏","","",""],[13404,13404,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏جَمَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْأَنْصَارَ ‏ ‏فَقَالَ أَفِيكُمْ أَحَدٌ مِنْ غَيْرِكُمْ فَقَالُوا لَا إِلَّا ‏ ‏ابْنُ أُخْتٍ لَنَا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْنُ أُخْتِ الْقَوْمِ مِنْهُمْ ‏ ‏قَالَ ‏ ‏حَجَّاجٌ ‏ ‏مِنْ أَنْفُسِهِمْ ‏ ‏فَقَالَ إِنَّ ‏ ‏قُرَيْشًا ‏ ‏حَدِيثُ ‏ ‏عَهْدٍ ‏ ‏بِجَاهِلِيَّةٍ وَمُصِيبَةٍ وَإِنِّي أَرَدْتُ أَنْ ‏ ‏أُجِيزَهُمْ ‏ ‏وَأَتَأَلَّفَهُمْ ‏ ‏أَمَا تَرْضَوْنَ أَنْ يَرْجِعَ النَّاسُ بِالدُّنْيَا وَتَرْجِعُونَ بِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى بُيُوتِكُمْ لَوْ سَلَكَ النَّاسُ وَادِيًا وَسَلَكَتْ ‏ ‏الْأَنْصَارُ ‏ ‏شِعْبًا ‏ ‏لَسَلَكْتُ ‏ ‏شِعْبَ ‏ ‏الْأَنْصَارِ ‏","","",""],[13405,13405,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ قَالَ فِي هَذِهِ الْآيَةِ ‏ { ‏إِنَّا فَتَحْنَا لَكَ فَتْحًا مُبِينًا ‏} ‏قَالَ ‏ ‏الْحُدَيْبِيَةُ ‏","","",""],[13406,13406,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ خَلْفَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَخَلْفَ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمْ ‏ ‏فَكَانُوا ‏ ‏لَا يَجْهَرُونَ بِ ‏ { ‏بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏}","","",""],[13407,13407,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَمَّا أَرَادَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَكْتُبَ إِلَى ‏ ‏الرُّومِ ‏ ‏كِتَابًا قَالُوا ‏ ‏إِنَّهُمْ لَا يَقْرَءُونَ كِتَابًا إِلَّا مَخْتُومًا قَالَ فَاتَّخَذَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَاتَمًا مِنْ فِضَّةٍ كَأَنِّي أَنْظُرُ إِلَى بَيَاضِهِ فِي يَدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَقْشُهُ ‏ ‏مُحَمَّدٌ ‏ ‏رَسُولُ اللَّهِ ‏","","",""],[13408,13408,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏و حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏يَهْرَمُ ‏ ‏ابْنُ ‏ ‏آدَمَ ‏ ‏وَتَبْقَى مِنْهُ اثْنَتَانِ الْحِرْصُ وَالْأَمَلُ ‏","","",""],[13409,13409,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجُ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّهُ قَالَ ‏ ‏انْشَقَّ ‏ ‏الْقَمَرُ عَلَى ‏ ‏عَهْدِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِرْقَتَيْنِ ‏","","",""],[13410,13410,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏سَمِعَ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏انْشَقَّ ‏ ‏الْقَمَرُ عَلَى ‏ ‏عَهْدِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[13411,13411,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏وَهِشَامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏عَدْوَى ‏ ‏وَلَا ‏ ‏طِيَرَةَ ‏ ‏وَلَا فَأْلَ قَالَ قِيلَ وَمَا الْفَأْلُ قَالَ الْكَلِمَةُ الطَّيِّبَةُ ‏ ‏وَاللَّفْظُ ‏ ‏لِمُحَمَّدِ بْنِ جَعْفَرٍ ‏","","",""],[13412,13412,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُمَّ إِنَّ الْعَيْشَ عَيْشُ ‏ ‏الْآخِرَهْ وَقَالَ ‏ ‏شُعْبَةُ ‏ ‏أَوْ قَالَ ‏ ‏اللَّهُمَّ لَا عَيْشَ إِلَّا عَيْشُ ‏ ‏الْآخِرَهْ ‏ ‏فَأَكْرِمْ ‏ ‏الْأَنْصَارَ ‏ ‏وَالْمُهَاجِرَهْ ‏","","",""],[13413,13413,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِلَحْمٍ فَقِيلَ لَهُ إِنَّهُ قَدْ تُصُدِّقَ بِهِ عَلَى ‏ ‏بَرِيرَةَ ‏ ‏فَقَالَ ‏ ‏هُوَ لَهَا ‏ ‏صَدَقَةٌ ‏ ‏وَهُوَ لَنَا هَدِيَّةٌ ‏","","",""],[13414,13414,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏بَرِيرَةَ ‏ ‏تُصُدِّقَ عَلَيْهَا ‏ ‏بِصَدَقَةٍ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هُوَ لَهَا ‏ ‏صَدَقَةٌ ‏ ‏وَلَنَا هَدِيَّةٌ ‏","","",""],[13415,13415,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏جَاءَ ‏ ‏أَعْرَابِيٌّ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏مَتَى السَّاعَةُ قَالَ وَمَا أَعْدَدْتَ لَهَا قَالَ حُبَّ اللَّهِ وَرَسُولِهِ قَالَ أَنْتَ مَعَ مَنْ أَحْبَبْتَ ‏","","",""],[13416,13416,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يُحَدِّثُ قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ نَبِيٍّ إِلَّا وَقَدْ أَنْذَرَ أُمَّتَهُ الْأَعْوَرَ الْكَافِرَ أَلَا إِنَّهُ أَعْوَرُ وَإِنَّ رَبَّكُمْ لَيْسَ بِأَعْوَرَ مَكْتُوبٌ بَيْنَ عَيْنَيْهِ ‏ ‏ك ‏ ‏ف ‏ ‏ر ‏","","",""],[13417,13417,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ أَحَدٍ يَدْخُلُ الْجَنَّةَ يُحِبُّ أَنْ يَرْجِعَ إِلَى الدُّنْيَا وَإِنَّ لَهُ مَا عَلَى الْأَرْضِ مِنْ شَيْءٍ غَيْرَ الشَّهِيدِ فَإِنَّهُ يَتَمَنَّى أَنْ يَرْجِعَ إِلَى الدُّنْيَا وَيُقْتَلَ عَشْرَ مَرَّاتٍ لِمَا يَرَى مِنْ ‏ ‏الْكَرَامَةِ ‏","","",""],[13418,13418,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ الْأَعْوَرُ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏وَيَزِيدُ بْنُ هَارُونَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏إِنَّ النَّبِيَّ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏مِنْ أَخَفِّ النَّاسِ صَلَاةً فِي تَمَامٍ ‏","","",""],[13419,13419,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنِي ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَخْرِجُوا مِنْ النَّارِ ‏ ‏وَقَالَ ‏ ‏حَجَّاجٌ ‏ ‏يَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏أَخْرِجُوا مِنْ النَّارِ ‏ ‏مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَمَنْ كَانَ فِي قَلْبِهِ مِنْ الْخَيْرِ مَا يَزِنُ ذَرَّةً أَخْرِجُوا مِنْ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَمَنْ كَانَ فِي قَلْبِهِ مِنْ الْخَيْرِ مَا يَزِنُ شَعِيرَةً أَخْرِجُوا مِنْ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَمَنْ كَانَ فِي قَلْبِهِ مِنْ الْخَيْرِ مَا يَزِنُ ‏ ‏بُرَّةً ‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏أَخْرِجُوا مِنْ النَّارِ فَذَكَرَ نَحْوَ حَدِيثِ ‏ ‏ابْنِ جَعْفَرٍ ‏ ‏وَزَادَ فِيهِ أَخْرِجُوا مِنْ النَّارِ مَنْ قَالَ لَا إِلَهَ إِلَّا اللَّهُ وَكَانَ فِي قَلْبِهِ مِنْ الْخَيْرِ مَا يَزِنُ دُودَةً ‏","","",""],[13420,13420,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏وَبَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏وَحَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏تُوَاصِلُوا ‏ ‏قَالُوا يَا رَسُولَ اللَّهِ إِنَّكَ ‏ ‏تُوَاصِلُ ‏ ‏قَالَ إِنِّي لَسْتُ كَأَحَدِكُمْ إِنِّي أَبِيتُ ‏ ‏وَقَالَ ‏ ‏بَهْزٌ ‏ ‏إِنِّي أَظَلُّ ‏ ‏أَوْ أَبِيتُ ‏ ‏أُطْعَمُ وَأُسْقَى ‏","","",""],[13421,13421,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى عَلَى رَجُلٍ يَسُوقُ ‏ ‏بَدَنَةً ‏ ‏قَالَ ‏ ‏ارْكَبْهَا قَالَ إِنَّهَا ‏ ‏بَدَنَةٌ ‏ ‏قَالَ ارْكَبْهَا قَالَ إِنَّهَا ‏ ‏بَدَنَةٌ ‏ ‏قَالَ ارْكَبْهَا قَالَ إِنَّهَا ‏ ‏بَدَنَةٌ ‏ ‏قَالَ ‏ ‏وَيْحَكَ ‏ ‏أَوْ وَيْلَكَ ‏ ‏ارْكَبْهَا ‏","","",""],[13422,13422,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ لِكُلِّ نَبِيٍّ دَعْوَةً قَدْ دَعَا بِهَا فِي أُمَّتِهِ وَإِنِّي قَدْ اخْتَبَأْتُ دَعْوَتِي شَفَاعَةً لِأُمَّتِي ‏","","",""],[13423,13423,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏أَخْبَرَنِي عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمَعَ ‏ ‏الْأَنْصَارَ ‏ ‏فَقَالَ هَلْ فِيكُمْ أَحَدٌ مِنْ غَيْرِكُمْ قَالُوا لَا إِلَّا ‏ ‏ابْنَ أُخْتٍ لَنَا ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْنُ أُخْتِ الْقَوْمِ مِنْ أَنْفُسِهِمْ ‏ ‏وَقَالَ مَرَّةً مِنْهُمْ ‏ ‏فَحَدَّثَنِي بِهِ عَنْ ‏ ‏أَنَسٍ ‏","","",""],[13424,13424,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏أَصْحَابَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا لِرَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ ‏ ‏أَهْلَ الْكِتَابِ ‏ ‏يُسَلِّمُونَ عَلَيْنَا فَكَيْفَ نَرُدُّ عَلَيْهِمْ قَالَ قُولُوا وَعَلَيْكُمْ ‏","","",""],[13425,13425,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَاَ ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقَاطَعُوا وَلَا تَبَاغَضُوا وَلَا تَحَاسَدُوا وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا ‏","","",""],[13426,13426,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُكْثِرُ أَنْ يَدْعُوَ ‏ ‏اللَّهُمَّ آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏فَذَكَرْتُ ذَلِكَ ‏ ‏لِقَتَادَةَ ‏ ‏فَقَالَ ‏ ‏قَتَادَةُ ‏ ‏كَانَ ‏ ‏أَنَسٌ ‏ ‏يَقُولُ هَذَا ‏","","",""],[13427,13427,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَنَسًا ‏ ‏عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏فَقَالَ لَمْ أَسْمَعْ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِ شَيْئًا قَالَ وَكَانَ ‏ ‏أَنَسٌ ‏ ‏يَكْرَهُهُ ‏","","",""],[13428,13428,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُتِيَ بِثَوْبٍ حَرِيرٍ فَجَعَلُوا يَمَسُّونَهُ وَيَنْظُرُونَ إِلَيْهِ فَقَالَ أَتَعْجَبُونَ مِنْ هَذَا لَمَنَادِيلُ ‏ ‏سَعْدِ بْنِ مُعَاذٍ ‏ ‏فِي الْجَنَّةِ خَيْرٌ مِنْ هَذَا وَأَلْيَنُ مِنْ هَذَا ‏ ‏أَوْ قَالَ مِنْدِيلُ ‏","","",""],[13429,13429,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ ‏أَنَا عِنْدَ ظَنِّ عَبْدِي بِي وَأَنَا مَعَهُ إِذَا دَعَانِي ‏","","",""],[13430,13430,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ابْنُ أُخْتِ الْقَوْمِ مِنْهُمْ ‏","","",""],[13431,13431,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَصْحَابُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنَامُونَ ثُمَّ يُصَلُّونَ وَلَا يَتَوَضَّئُونَ ‏","","",""],[13432,13432,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏و حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏قَالَ سَمِعْتُ ‏ ‏شُعْبَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏جَمَعَ الْقُرْآنَ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَرْبَعَةٌ ‏ ‏قَالَ ‏ ‏يَحْيَى ‏ ‏كُلُّهُمْ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏أُبَيُّ بْنُ كَعْبٍ ‏ ‏وَمُعَاذُ بْنُ جَبَلٍ ‏ ‏وَزَيْدُ بْنُ ثَابِتٍ ‏ ‏وَأَبُو زَيْدٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏مَنْ ‏ ‏أَبُو زَيْدٍ ‏ ‏قَالَ ‏ ‏أَحَدُ عُمُومَتِي ‏","","",""],[13433,13433,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنِي ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏نُهِيَ عَنْ الشُّرْبِ قَائِمًا قَالَ قُلْتُ فَالْأَكْلُ قَالَ ذَاكَ أَشَدُّ ‏","","",""],[13434,13434,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ سَعِيدٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏الْحَجَرُ الْأَسْوَدُ مِنْ الْجَنَّةِ ‏","","",""],[13435,13435,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏وَأَبُو نُوحٍ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏أَبُو نُوحٍ ‏ ‏وسَمِعَهُ مِنْهُ ‏ ‏و حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏هَاشِمٍ ‏ ‏وَالْحَجَّاجِ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَخَفِّ النَّاسِ صَلَاةً فِي تَمَامٍ ‏","","",""],[13436,13436,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أَلَا أُحَدِّثُكُمْ حَدِيثًا سَمِعْتُهُ مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَذْهَبُ الرِّجَالُ ‏ ‏وَيَبْقَى النِّسَاءُ ‏","","",""],[13437,13437,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَلْمَدِينَةِ ‏ ‏يَأْتِيهَا ‏ ‏الدَّجَّالُ ‏ ‏فَيَجِدُ الْمَلَائِكَةَ ‏ ‏عَلَيْهِمْ السَّلَام ‏ ‏يَحْرُسُونَهَا فَلَا يَقْرَبُهَا ‏ ‏الدَّجَّالُ ‏ ‏وَلَا الطَّاعُونُ إِنْ شَاءَ اللَّهُ تَعَالَى ‏","","",""],[13438,13438,"","","‏ ‏حَدَّثَنَا ‏ ‏يَزِيدُ بْنُ هَارُونَ ‏ ‏أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏و حَدَّثَنِي ‏ ‏الضَّحَّاكُ يَعْنِي ابْنَ مَخْلَدٍ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏و حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ يَزِيدَ الْوَاسِطِيُّ ‏ ‏عَنْ ‏ ‏هِشَامٍ الدَّسْتُوَائِيِّ ‏ ‏وَشُعْبَةَ ‏ ‏جَمِيعًا ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ الْبُزَاقُ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏وَالضَّحَّاكُ بْنُ مَخْلَدٍ ‏ ‏فِي حَدِيثِهِمَا ‏ ‏النُّخَاعَةُ ‏ ‏فِي الْمَسْجِدِ خَطِيئَةٌ وَكَفَّارَتُهَا دَفْنُهَا ‏","","",""],[13439,13439,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏أَخْبَرَنِي أَنَّهُ سَمِعَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا ‏ ‏عَدْوَى ‏ ‏وَلَا ‏ ‏طِيَرَةَ ‏ ‏وَيُعْجِبُنِي الْفَأْلُ ‏ ‏قُلْتُ وَمَا الْفَأْلُ ‏ ‏قَالَ ‏ ‏الْكَلِمَةُ الطَّيِّبَةُ ‏","","",""],[13440,13440,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي التَّيَّاحِ ‏ ‏وَقَتَادَةَ ‏ ‏وَحَمْزَةَ الضَّبِّيِّ ‏ ‏أَنَّهُمْ سَمِعُوا ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بُعِثْتُ أَنَا وَالسَّاعَةُ هَكَذَا وَأَشَارَ بِالسَّبَّابَةِ وَالْوُسْطَى ‏ ‏وَكَانَ ‏ ‏قَتَادَةُ ‏ ‏يَقُولُ ‏ ‏كَفَضْلِ إِحْدَاهُمَا عَلَى الْأُخْرَى ‏","","",""],[13441,13441,"","","‏ ‏حَدَّثَنَا ‏ ‏الْأَسْوَدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَنَتَ ‏ ‏شَهْرًا يَلْعَنُ ‏ ‏رِعْلًا ‏ ‏وَذَكْوَانَ ‏ ‏وَعُصَيَّةَ ‏ ‏عَصَوْا اللَّهَ وَرَسُولَهُ ‏","","",""],[13442,13442,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو سَعِيدٍ ‏ ‏مَوْلَى ‏ ‏بَنِي هَاشِمٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَنَتَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَهْرًا يَدْعُو عَلَى ‏ ‏رِعْلٍ ‏ ‏وَذَكْوَانَ ‏ ‏وَبَنِي فُلَانٍ ‏ ‏وَعُصَيَّةَ ‏ ‏عَصَوْا اللَّهَ وَرَسُولَهُ ‏ ‏قَالَ ‏ ‏مَرْوَانُ ‏ ‏يَعْنِي فَقُلْتُ ‏ ‏لِأَنَسٍ ‏ ‏قَنَتَ ‏ ‏عُمَرُ ‏ ‏قَالَ ‏ ‏عُمَرُ ‏ ‏لَا ‏","","",""],[13443,13443,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ أَحَدُكُمْ فِي صَلَاةٍ فَإِنَّهُ ‏ ‏يُنَاجِي ‏ ‏رَبَّهُ عَزَّ وَجَلَّ فَلَا يَتْفِلَنَّ بَيْنَ يَدَيْهِ وَلَا عَنْ يَمِينِهِ وَلْيَتْفِلْ عَنْ يَسَارِهِ أَوْ تَحْتَ قَدَمِهِ ‏","","",""],[13444,13444,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ بَشَّارٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏إِنْ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَيُلَاطِفُنَا كَثِيرًا حَتَّى إِنَّهُ قَالَ لِأَخٍ لِي صَغِيرٍ ‏ ‏يَا ‏ ‏أَبَا عُمَيْرٍ ‏ ‏مَا فَعَلَ ‏ ‏النُّغَيْرُ ‏","","",""],[13445,13445,"","","‏ ‏حَدَّثَنَا ‏ ‏حَجَّاجٌ ‏ ‏حَدَّثَنِي ‏ ‏شُعْبَةُ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏اللَّهُمَّ إِنَّ الْخَيْرَ خَيْرُ ‏ ‏الْآخِرَهْ أَوْ قَالَ ‏ ‏اللَّهُمَّ لَا خَيْرَ إِلَّا خَيْرَ ‏ ‏الْآخِرَهْ ‏ ‏فَاغْفِرْ ‏ ‏لِلْأَنْصَارِ ‏ ‏وَالْمُهَاجِرَهْ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏كَانَ يَقُولُ ‏ ‏قَتَادَةُ ‏ ‏هَذِهِ فِي قَصَصِهِ ‏","","",""],[13446,13446,"","","‏ ‏حَدَّثَنَا ‏ ‏وَكِيعٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَبَحَ وَسَمَّى وَكَبَّرَ ‏","","",""],[13447,13447,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ اللَّهِ السُّلَمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏صَلَّيْتُ خَلْفَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَخَلْفَ ‏ ‏أَبِي بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمْ ‏ ‏فَلَمْ يَكُونُوا يَسْتَفْتِحُونَ الْقِرَاءَةَ بِ ‏ { ‏بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ ‏} ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏فَقُلْتُ ‏ ‏لِقَتَادَةَ ‏ ‏أَسَمِعْتَهُ مِنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏نَعَمْ نَحْنُ سَأَلْنَاهُ عَنْهُ ‏","","",""],[13448,13448,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ اللَّهِ السُّلَمِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبُو دَاوُدَ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏انْشَقَّ ‏ ‏الْقَمَرُ عَلَى ‏ ‏عَهْدِ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[13449,13449,"","","‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يَكُونَ اللَّهُ وَرَسُولُهُ أَحَبَّ إِلَيْهِ مِمَّا سِوَاهُمَا وَحَتَّى يُقْذَفَ فِي النَّارِ أَحَبَّ إِلَيْهِ مِنْ أَنْ يَعُودَ فِي كُفْرٍ بَعْدَ إِذْ نَجَّاهُ اللَّهُ مِنْهُ وَلَا يُؤْمِنُ أَحَدُكُمْ حَتَّى أَكُونَ أَحَبَّ إِلَيْهِ مِنْ وَلَدِهِ وَوَالِدِهِ وَالنَّاسِ أَجْمَعِينَ ‏ ‏حَدَّثَنَا ‏ ‏رَوْحٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏مَنْصُورًا ‏ ‏قَالَ سَمِعْتُ ‏ ‏طَلْقَ بْنَ حَبِيبٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِثْلَهُ ‏","","",""],[13450,13450,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ اللَّهِ السُّلَمِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏حَرَمِيُّ بْنُ عُمَارَةَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏قَتَادَةُ ‏ ‏وَحَمَّادُ بْنُ أَبِي سُلَيْمَانَ ‏ ‏وَسُلَيْمَانُ التَّيْمِيُّ ‏ ‏سَمِعُوا ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[13451,13451,"","","‏ ‏حَدَّثَنَا ‏ ‏شَبَابَةُ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏عَبْدَ الرَّحْمَنِ بْنَ عَوْفٍ ‏ ‏تَزَوَّجَ عَلَى وَزْنِ ‏ ‏نَوَاةٍ ‏ ‏مِنْ ذَهَبٍ ‏ ‏قَالَ ‏ ‏فَكَانَ ‏ ‏الْحَكَمُ ‏ ‏يَأْخُذُ بِهِ ‏","","",""],[13452,13452,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُؤْمِنُ أَحَدُكُمْ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ ‏","","",""],[13453,13453,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرِ بْنُ أَبِي شَيْبَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو خَالِدٍ الْأَحْمَرُ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏وَشُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا مِنْ نَفْسٍ تَمُوتُ لَهَا عِنْدَ اللَّهِ عَزَّ وَجَلَّ خَيْرٌ يَسُرُّهَا أَنْ تَرْجِعَ إِلَى الدُّنْيَا وَأَنَّ لَهَا الدُّنْيَا وَمَا فِيهَا إِلَّا الشَّهِيدَ ‏ ‏يَتَمَنَّى أَنْ يَرْجِعَ فَيُقْتَلَ فِي الدُّنْيَا لِمَا يَرَى مِنْ ‏ ‏فَضْلِ الشَّهَادَةِ ‏","","",""],[13454,13454,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ اللَّهِ السُّلَمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ أَخَفِّ النَّاسِ صَلَاةً فِي تَمَامٍ ‏","","",""],[13455,13455,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ اللَّهِ السُّلَمِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏سَمِعَ ‏ ‏أَنَسًا ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُعْجِبُهُ ‏ ‏الدُّبَّاءُ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏فَجَعَلْتُ أَضَعُهُ بَيْنَ يَدَيْهِ ‏","","",""],[13456,13456,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَبْدِ اللَّهِ السُّلَمِيُّ الْعَنْبَرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو دَاوُدَ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَنَسًا ‏ ‏عَنْ ‏ ‏نَبِيذِ ‏ ‏الْجَرِّ ‏ ‏فَقَالَ لَمْ أَسْمَعْ مِنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيهِ شَيْئًا وَكَانَ ‏ ‏أَنَسٌ ‏ ‏يَكْرَهُهُ ‏","","",""],[13457,13457,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِىُّ ‏ ‏حَدَّثَنَا ‏ ‏حَرَمِيُّ بْنُ عُمَارَةَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُلْقِي فِي النَّارِ وَتَقُولُ ‏ { ‏هَلْ مِنْ مَزِيدٍ ‏} ‏حَتَّى يَضَعَ قَدَمَهُ ‏ ‏أَوْ رِجْلَهُ ‏ ‏عَلَيْهَا وَتَقُولُ قَطْ قَطْ ‏","","",""],[13458,13458,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ أَحْمَدَ الْجُنَيْدِيُّ ‏ ‏حَدَّثَنَا ‏ ‏رَجُلٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَكَانَ بِهَذَا الْحَدِيثِ مُعْجَبًا ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَوُّوا صُفُوفَكُمْ فَإِنَّ تَسْوِيَةَ الصَّفِّ مِنْ تَمَامِ الصَّلَاةِ ‏","","",""],[13459,13459,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ عُمَرَ الْقَوَارِيرِيُّ ‏ ‏حَدَّثَنَا ‏ ‏حَرَمِيُّ بْنُ عُمَارَةَ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[13460,13460,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ مُعَاذٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَحُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏مُطِرْنَا ‏ ‏بَرَدًا ‏ ‏وَأَبُو طَلْحَةَ ‏ ‏صَائِمٌ فَجَعَلَ يَأْكُلُ مِنْهُ قِيلَ لَهُ أَتَأْكُلُ وَأَنْتَ صَائِمٌ فَقَالَ إِنَّمَا هَذَا بَرَكَةٌ ‏","","",""],[13461,13461,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ سَعْدِ بْنِ إِبْرَاهِيمَ الزُّهْرِيُّ أَبُو الْقَاسِمِ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمِّي ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ بْنِ الْحَجَّاجِ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُضَحِّي بِكَبْشَيْنِ أَقْرَنَيْنِ ‏ ‏أَمْلَحَيْنِ ‏ ‏وَيُسَمِّي وَيُكَبِّرُ وَلَقَدْ رَأَيْتُهُ يَذْبَحُهُمَا بِيَدِهِ وَاضِعًا عَلَى ‏ ‏صِفَاحِهِمَا ‏ ‏قَدَمَهُ ‏","","",""],[13462,13462,"","","‏ ‏حَدَّثَنَا ‏ ‏عُبَيْدُ اللَّهِ بْنُ سَعِيدٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏عَمِّي ‏ ‏يَعْقُوبُ ‏ ‏عَنْ ‏ ‏شَرِيكٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اعْتَدِلُوا فِي سُجُودِكُمْ وَلَا ‏ ‏يَفْتَرِشْ ‏ ‏أَحَدُكُمْ ذِرَاعَيْهِ ‏ ‏افْتِرَاشَ ‏ ‏الْكَلْبِ أَتِمُّوا الرُّكُوعَ وَالسُّجُودَ فَوَاللَّهِ إِنِّي لَأَرَاكُمْ مِنْ بَعْدِي ‏ ‏أَوْ مِنْ بَعْدِ ظَهْرِي ‏ ‏إِذَا رَكَعْتُمْ وَإِذَا سَجَدْتُمْ ‏","","",""],[13463,13463,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏يَعْقُوبُ بْنُ إِبْرَاهِيمَ الدَّوْرَقِيُّ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏سَعِيدُ بْنُ عَامِرٍ ‏ ‏عَنْ ‏ ‏شُعْبَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ عُمُومَةً لَهُ شَهِدُوا عِنْدَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى رُؤْيَةِ الْهِلَالِ ‏ ‏فَأَمَرَ النَّاسَ أَنْ يُفْطِرُوا وَأَنْ يَخْرُجُوا إِلَى عِيدِهِمْ مِنْ الْغَدِ ‏","","",""],[13464,13464,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏هَوَازِنَ ‏ ‏جَاءَتْ يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏بِالنِّسَاءِ وَالصِّبْيَانِ وَالْإِبِلِ وَالْغَنَمِ فَجَعَلُوهَا صُفُوفًا وَكَثُرْنَ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا الْتَقَوْا ‏ ‏وَلَّى ‏ ‏الْمُسْلِمُونَ ‏ ‏مُدْبِرِينَ ‏ ‏كَمَا قَالَ اللَّهُ عَزَّ وَجَلَّ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا عِبَادَ اللَّهِ ‏ ‏أَنَا عَبْدُ اللَّهِ وَرَسُولُهُ ثُمَّ قَالَ يَا مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏أَنَا عَبْدُ اللَّهِ وَرَسُولُهُ قَالَ فَهَزَمَ اللَّهُ الْمُشْرِكِينَ وَلَمْ يَضْرِبُوا بِسَيْفٍ وَلَمْ يَطْعَنُوا بِرُمْحٍ قَالَ وَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَئِذٍ مَنْ قَتَلَ كَافِرًا فَلَهُ ‏ ‏سَلَبُهُ ‏ ‏قَالَ فَقَتَلَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏يَوْمَئِذٍ عِشْرِينَ رَجُلًا وَأَخَذَ ‏ ‏أَسْلَابَهُمْ ‏ ‏وَقَالَ ‏ ‏أَبُو قَتَادَةَ ‏ ‏يَا رَسُولَ اللَّهِ إِنِّي ضَرَبْتُ رَجُلًا عَلَى ‏ ‏حَبْلِ الْعَاتِقِ ‏ ‏وَعَلَيْهِ ‏ ‏دِرْعٌ ‏ ‏لَهُ ‏ ‏وَأُجْهِضْتُ ‏ ‏عَنْهُ ‏ ‏وَقَدْ قَالَ ‏ ‏حَمَّادٌ ‏ ‏أَيْضًا فَأُعْجِلْتُ عَنْهُ ‏ ‏فَانْظُرْ مَنْ أَخَذَهَا قَالَ فَقَامَ رَجُلٌ فَقَالَ أَنَا أَخَذْتُهَا فَأَرْضِهِ مِنْهَا وَأَعْطِنِيهَا وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُسْأَلُ شَيْئًا إِلَّا أَعْطَاهُ أَوْ سَكَتَ قَالَ فَسَكَتَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَقَالَ ‏ ‏عُمَرُ ‏ ‏وَاللَّهِ لَا ‏ ‏يُفِيئُهَا ‏ ‏اللَّهُ عَلَى أَسَدٍ مِنْ أُسْدِهِ ‏ ‏وَيُعْطِيكَهَا قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَدَقَ ‏ ‏عُمَرُ ‏ ‏فَضَحِكَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَالَ صَدَقَ ‏ ‏عُمَرُ ‏ ‏وَلَقِيَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏وَمَعَهَا خِنْجَرٌ فَقَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏مَا هَذَا مَعَكِ قَالَتْ أَرَدْتُ إِنْ دَنَا مِنِّي بَعْضُ الْمُشْرِكِينَ أَنْ ‏ ‏أَبْعَجَ ‏ ‏بِهِ بَطْنَهُ فَقَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏أَلَا تَسْمَعُ مَا تَقُولُ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏قَالَتْ يَا رَسُولَ اللَّهِ اقْتُلْ مَنْ بَعْدَنَا مِنْ ‏ ‏الطُّلَقَاءِ ‏ ‏انْهَزَمُوا بِكَ فَقَالَ إِنَّ اللَّهَ قَدْ كَفَى وَأَحْسَنَ يَا ‏ ‏أُمَّ سُلَيْمٍ ‏","","",""],[13465,13465,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمُ بْنُ أَخْضَرَ ‏ ‏حَدَّثَنَا ‏ ‏ابْنُ عَوْنٍ ‏ ‏حَدَّثَنِي ‏ ‏هِشَامُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَمَّا كَانَ يَوْمُ ‏ ‏حُنَيْنٍ ‏ ‏وَجَمَعَتْ ‏ ‏هَوَازِنُ ‏ ‏وَغَطَفَانُ ‏ ‏لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَمْعًا كَثِيرًا وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَئِذٍ فِي عَشَرَةِ آلَافٍ ‏ ‏أَوْ أَكْثَرَ مِنْ عَشَرَةِ آلَافٍ ‏ ‏قَالَ وَمَعَهُ ‏ ‏الطُّلَقَاءُ ‏ ‏قَالَ فَجَاءُوا بِالنَّعَمِ ‏ ‏وَالذُّرِّيَّةِ ‏ ‏فَجُعِلُوا خَلْفَ ظُهُورِهِمْ قَالَ فَلَمَّا الْتَقَوْا ‏ ‏وَلَّى ‏ ‏النَّاسُ قَالَ وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَئِذٍ عَلَى بَغْلَةٍ بَيْضَاءَ قَالَ فَنَزَلَ وَقَالَ إِنِّي عَبْدُ اللَّهِ وَرَسُولُهُ قَالَ وَنَادَى يَوْمَئِذٍ نِدَاءَيْنِ لَمْ يُخْلَطْ بَيْنَهُمَا كَلَامٌ فَالْتَفَتَ عَنْ يَمِينِهِ فَقَالَ أَيْ مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏قَالُوا لَبَّيْكَ يَا رَسُولَ اللَّهِ أَبْشِرْ نَحْنُ مَعَكَ ثُمَّ الْتَفَتَ عَنْ يَسَارِهِ فَقَالَ أَيْ مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏قَالُوا لَبَّيْكَ يَا رَسُولَ اللَّهِ نَحْنُ مَعَكَ ثُمَّ نَزَلَ بِالْأَرْضِ وَالْتَقَوْا فَهَزَمُوا وَأَصَابُوا مِنْ الْغَنَائِمِ فَأَعْطَى النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الطُّلَقَاءَ ‏ ‏وَقَسَمَ فِيهَا فَقَالَتْ ‏ ‏الْأَنْصَارُ ‏ ‏نُدْعَى عِنْدَ الْكَرَّةِ وَتُقْسَمُ الْغَنِيمَةُ لِغَيْرِنَا فَبَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَجَمَعَهُمْ وَقَعَدَ فِي ‏ ‏قُبَّةٍ ‏ ‏فَقَالَ أَيْ مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏مَا حَدِيثٌ بَلَغَنِي عَنْكُمْ فَسَكَتُوا ثُمَّ قَالَ يَا مَعْشَرَ ‏ ‏الْأَنْصَارِ ‏ ‏لَوْ أَنَّ النَّاسَ سَلَكُوا وَادِيًا وَسَلَكَتْ ‏ ‏الْأَنْصَارُ ‏ ‏شِعْبًا ‏ ‏لَأَخَذْتُ ‏ ‏شِعْبَ ‏ ‏الْأَنْصَارِ ‏ ‏ثُمَّ قَالَ أَمَا تَرْضَوْنَ أَنْ يَذْهَبَ النَّاسُ بِالدُّنْيَا وَتَذْهَبُونَ بِرَسُولِ اللَّهِ ‏ ‏تَحُوزُونَهُ ‏ ‏إِلَى بُيُوتِكُمْ قَالُوا رَضِينَا يَا رَسُولَ اللَّهِ رَضِينَا ‏ ‏قَالَ ‏ ‏ابْنُ عَوْنٍ ‏ ‏قَالَ ‏ ‏هِشَامُ بْنُ زَيْدٍ ‏ ‏فَقُلْتُ ‏ ‏لِأَنَسٍ ‏ ‏وَأَنْتَ تُشَاهِدُ ذَاكَ قَالَ ‏ ‏فَأَيْنَ أَغِيبُ عَنْ ذَاكَ ‏","","",""],[13466,13466,"","","‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ حَرْبٍ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏غُلَامًا ‏ ‏يَهُودِيًّا كَانَ يَخْدُمُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَرِضَ فَأَتَاهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعُودُهُ ‏ ‏فَقَعَدَ عِنْدَ رَأْسِهِ فَقَالَ لَهُ أَسْلِمْ فَنَظَرَ إِلَى أَبِيهِ وَهُوَ عِنْدَ رَأْسِهِ فَقَالَ أَطِعْ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏فَأَسْلَمَ فَخَرَجَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ عِنْدِهِ وَهُوَ يَقُولُ ‏ ‏الْحَمْدُ لِلَّهِ الَّذِي أَنْقَذَهُ بِي مِنْ النَّارِ ‏","","",""],[13467,13467,"","","‏ ‏حَدَّثَنَا ‏ ‏يُونُسُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏وَلَا أَعْلَمُهُ إِلَّا ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ غُلَامًا مِنْ ‏ ‏الْيَهُودِ ‏ ‏كَانَ يَخْدُمُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَمَرِضَ فَأَتَاهُ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَعُودُهُ ‏ ‏وَهُوَ بِالْمَوْتِ فَدَعَاهُ إِلَى الْإِسْلَامِ فَنَظَرَ الْغُلَامُ إِلَى أَبِيهِ وَهُوَ عِنْدَ رَأْسِهِ فَقَالَ لَهُ أَبُوهُ أَطِعْ ‏ ‏أَبَا الْقَاسِمِ ‏ ‏فَأَسْلَمَ ثُمَّ مَاتَ فَخَرَجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ عِنْدِهِ وَهُوَ يَقُولُ ‏ ‏الْحَمْدُ لِلَّهِ الَّذِي أَنْقَذَهُ بِي مِنْ النَّارِ ‏","","",""],[13468,13468,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمُ بْنُ الْقَاسِمِ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى يَعْنِي ابْنَ طَهْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏إِنَّ لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عِنْدِي سِرًّا لَا أُخْبِرُ بِهِ أَحَدًا أَبَدًا حَتَّى أَلْقَاهُ ‏","","",""],[13469,13469,"","","‏ ‏حَدَّثَنَا ‏ ‏هَاشِمٌ ‏ ‏حَدَّثَنَا ‏ ‏عِيسَى بْنُ طَهْمَانَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏سَمِعْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏مَنْ كَذَبَ عَلَيَّ مُتَعَمِّدًا ‏ ‏فَلْيَتَبَوَّأْ ‏ ‏مَقْعَدَهُ مِنْ النَّارِ ‏","","",""],[13470,13470,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ آدَمَ ‏ ‏حَدَّثَنَا ‏ ‏شَرِيكٌ ‏ ‏عَنْ ‏ ‏مَنْصُورٍ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏يَرْفَعُهُ إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ جَمَعَ بَيْنَ الْعُمْرَةِ وَالْحَجِّ فَقَالَ ‏ ‏لَبَّيْكَ بِحَجَّةٍ وَعُمْرَةٍ مَعًا ‏","","",""],[13471,13471,"","","‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ بْنُ خَالِدٍ ‏ ‏أَخْبَرَنَا ‏ ‏رَبَاحٌ ‏ ‏عَنْ ‏ ‏مَعْمَرٍ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْتَقَ ‏ ‏صَفِيَّةَ ابْنَةَ حُيَيٍّ ‏ ‏وَجَعَلَ عِتْقَهَا ‏ ‏صَدَاقَهَا ‏","","",""],[13472,13472,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَمْرَو بْنَ عَامِرٍ الْأَنْصَارِيَّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ الْمُؤَذِّنُ إِذَا أَذَّنَ قَامَ ‏ ‏أَصْحَابُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَبْتَدِرُونَ ‏ ‏السَّوَارِيَ ‏ ‏حَتَّى يَخْرُجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُمْ كَذَلِكَ ‏ ‏يَعْنِي الرَّكْعَتَيْنِ قَبْلَ الْمَغْرِبِ ‏ ‏وَلَمْ يَكُنْ بَيْنَ الْأَذَانِ وَالْإِقَامَةِ إِلَّا قَرِيبٌ ‏","","",""],[13473,13473,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏حَدَّثَنَا ‏ ‏عُثْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏عَنْ ‏ ‏سَالِمِ بْنِ أَبِي الْجَعْدِ ‏ ‏عَنْ ‏ ‏سَعْدٍ ‏ ‏مَوْلَى ‏ ‏الْحَسَنِ بْنِ عَلِيٍّ ‏ ‏قَالَ ‏ ‏خَرَجْنَا مَعَ ‏ ‏عَلِيٍّ ‏ ‏فَأَتَيْنَا ‏ ‏ذَا الْحُلَيْفَةِ ‏ ‏فَقَالَ ‏ ‏عَلِيٌّ ‏ ‏إِنِّي أُرِيدُ أَنْ أَجْمَعَ بَيْنَ الْحَجِّ وَالْعُمْرَةِ فَمَنْ أَرَادَ ذَلِكَ فَلْيَقُلْ كَمَا أَقُولُ ثُمَّ لَبَّى قَالَ لَبَّيْكَ بِحَجَّةٍ وَعُمْرَةٍ مَعًا ‏ ‏قَالَ وَقَالَ ‏ ‏سَالِمٌ ‏ ‏وَقَدْ أَخْبَرَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ وَاللَّهِ إِنَّ رِجْلِي لَتَمَسُّ رِجْلَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَإِنَّهُ ‏ ‏لَيُهِلُّ ‏ ‏بِهِمَا جَمِيعًا ‏","","",""],[13474,13474,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏إِسْمَاعِيلَ السُّدِّيِّ ‏ ‏قَالَ سَأَلْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ابْنِهِ ‏ ‏إِبْرَاهِيمَ ‏ ‏قَالَ لَا أَدْرِي رَحْمَةُ اللَّهِ عَلَى ‏ ‏إِبْرَاهِيمَ ‏ ‏لَوْ عَاشَ كَانَ صِدِّيقًا نَبِيًّا قَالَ قُلْتُ كَيْفَ أَنْصَرِفُ إِذَا صَلَّيْتُ عَنْ يَمِينِي أَوْ عَنْ يَسَارِي قَالَ أَمَّا أَنَا فَرَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَنْصَرِفُ عَنْ يَمِينِهِ ‏","","",""],[13475,13475,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ غِيَاثٍ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏قَالَ ‏ ‏سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏وَقَالَ لَهُ قَائِلٌ بَلَغَكَ أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَا ‏ ‏حِلْفَ ‏ ‏فِي الْإِسْلَامِ قَالَ فَغَضِبَ ثُمَّ قَالَ بَلَى بَلَى قَدْ ‏ ‏حَالَفَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ ‏ ‏قُرَيْشٍ ‏ ‏وَالْأَنْصَارِ ‏ ‏فِي دَارِهِ ‏","","",""],[13476,13476,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏عَاصِمٌ الْأَحْوَلُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏حَالَفَ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ ‏ ‏الْمُهَاجِرِينَ ‏ ‏وَالْأَنْصَارِ ‏ ‏فِي دَارِ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏","","",""],[13477,13477,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏حُمَيْدٌ ‏ ‏عَنِ ‏ ‏الْحَسَنِ ‏ ‏وَعَنْ ‏ ‏أَنَسٍ ‏ ‏فِيمَا يَحْسَبُ ‏ ‏حَمَّادٌ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَرَجَ ‏ ‏يَتَوَكَّأُ ‏ ‏عَلَى ‏ ‏أُسَامَةَ بْنِ زَيْدٍ ‏ ‏وَهُوَ ‏ ‏مُتَوَشِّحٌ ‏ ‏بِثَوْبِ قُطْنٍ قَدْ ‏ ‏خَالَفَ ‏ ‏بَيْنَ طَرَفَيْهِ فَصَلَّى بِالنَّاسِ ‏","","",""],[13478,13478,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَجُلًا كَانَ يُتَّهَمُ بِامْرَأَةٍ ‏ ‏فَبَعَثَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلِيًّا ‏ ‏لِيَقْتُلَهُ فَوَجَدَهُ فِي ‏ ‏رَكِيَّةٍ ‏ ‏يَتَبَرَّدُ ‏ ‏فِيهَا فَقَالَ لَهُ نَاوِلْنِي يَدَكَ فَنَاوَلَهُ يَدَهُ فَإِذَا هُوَ ‏ ‏مَجْبُوبٌ ‏ ‏لَيْسَ لَهُ ذَكَرٌ فَأَتَى رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ فَقَالَ وَاللَّهِ يَا رَسُولَ اللَّهِ إِنَّهُ ‏ ‏لَمَجْبُوبٌ ‏ ‏مَا لَه مِنْ ذَكَرٍ ‏","","",""],[13479,13479,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏خَالِدٌ الْحَذَّاءُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَرْحَمُ أُمَّتِي بِأُمَّتِي ‏ ‏أَبُو بَكْرٍ ‏ ‏وَأَشَدُّهُمْ فِي دِينِ اللَّهِ ‏ ‏عُمَرُ ‏ ‏وَقَالَ ‏ ‏عَفَّانُ ‏ ‏مَرَّةً فِي أَمْرِ اللَّهِ ‏ ‏عُمَرُ ‏ ‏وَأَصْدَقُهُمْ حَيَاءً ‏ ‏عُثْمَانُ ‏ ‏وَأَفْرَضُهُمْ ‏ ‏زَيْدُ بْنُ ثَابِتٍ ‏ ‏وَأَقْرَؤُهُمْ لِكِتَابِ اللَّهِ ‏ ‏أُبَيُّ بْنُ كَعْبٍ ‏ ‏وَأَعْلَمُهُمْ بِالْحَلَالِ وَالْحَرَامِ ‏ ‏مُعَاذُ بْنُ جَبَلٍ ‏ ‏أَلَا وَإِنَّ لِكُلِّ أُمَّةٍ أَمِينًا وَإِنَّ أَمِينَ هَذِهِ الْأُمَّةِ ‏ ‏أَبُو عُبَيْدَةَ بْنُ الْجَرَّاحِ ‏ ‏رَضِيَ اللَّهُ عَنْهُمْ ‏ ‏أَجْمَعِينَ ‏","","",""],[13480,13480,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏وُهَيْبٌ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَيَرِدَنَّ الْحَوْضَ عَلَيَّ رِجَالٌ حَتَّى إِذَا رَأَيْتُهُمْ رُفِعُوا إِلَيَّ ‏ ‏فَاخْتُلِجُوا ‏ ‏دُونِي فَلَأَقُولَنَّ يَا رَبِّ أَصْحَابِي أَصْحَابِي فَيُقَالُ إِنَّكَ لَا تَدْرِي مَا ‏ ‏أَحْدَثُوا ‏ ‏بَعْدَكَ ‏","","",""],[13481,13481,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الْعَزِيزِ بْنَ صُهَيْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يُحَدِّثُ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنَّهُ قَالَ ‏ ‏مَنْ لَبِسَ الْحَرِيرَ فِي الدُّنْيَا فَلَنْ يَلْبَسَهُ فِي الْآخِرَةِ ‏","","",""],[13482,13482,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَسَحَّرُوا فَإِنَّ فِي السُّحُورِ بَرَكَةً ‏","","",""],[13483,13483,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يَتَمَنَّى أَحَدُكُمْ الْمَوْتَ مِنْ ضُرٍّ نَزَلَ بِهِ فَإِنْ كَانَ لَا بُدَّ فَاعِلًا فَلْيَقُلْ اللَّهُمَّ أَحْيِنِي مَا كَانَتْ الْحَيَاةُ خَيْرًا لِي وَتَوَفَّنِي إِذَا كَانَتْ الْوَفَاةُ خَيْرًا لِي ‏","","",""],[13484,13484,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏عَبْدَ الْعَزِيزِ بْنَ صُهَيْبٍ ‏ ‏يُحَدِّثُ عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُضَحِّي بِكَبْشَيْنِ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏وَأَنَا أُضَحِّي بِهِمَا ‏","","",""],[13485,13485,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّتْ عَلَيْهِ جَنَازَةٌ فَأَثْنَوْا عَلَيْهَا خَيْرًا فَقَالَ وَجَبَتْ وَجَبَتْ وَمَرَّتْ عَلَيْهِ جَنَازَةٌ فَأَثْنَوْا عَلَيْهَا شَرًّا فَقَالَ وَجَبَتْ وَجَبَتْ فَقَالَ ‏ ‏عُمَرُ ‏ ‏يَا رَسُولَ اللَّهِ قَوْلُكَ الْأَوَّلُ وَجَبَتْ وَقَوْلُكَ الْآخَرُ وَجَبَتْ قَالَ أَمَّا الْأَوَّلُ فَأَثْنَوْا عَلَيْهَا خَيْرًا فَقُلْتُ وَجَبَتْ لَهُ الْجَنَّةُ وَأَمَّا الْآخَرُ فَأَثْنَوْا عَلَيْهَا شَرًّا فَقُلْتُ وَجَبَتْ لَهُ النَّارُ وَأَنْتُمْ شُهَدَاءُ اللَّهِ فِي أَرْضِهِ ‏","","",""],[13486,13486,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُجَوِّزُهَا وَيُكْمِلُهَا ‏ ‏يَعْنِي يُخَفِّفُ الصَّلَاةَ ‏","","",""],[13487,13487,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏تَزَوَّجَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَفِيَّةَ ‏ ‏فَقَالَ لَهُ ‏ ‏ثَابِتٌ ‏ ‏مَا أَصْدَقَهَا قَالَ ‏ ‏أَصْدَقَهَا ‏ ‏نَفْسَهَا أَعْتَقَهَا وَتَزَوَّجَهَا ‏","","",""],[13488,13488,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ الْعَزِيزِ بْنِ صُهَيْبٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا أَتَى ‏ ‏الْخَلَاءَ ‏ ‏قَالَ أَعُوذُ بِاللَّهِ مِنْ ‏ ‏الْخُبْثِ ‏ ‏وَالْخَبِيثِ ‏ ‏أَوْ ‏ ‏الْخَبَائِثِ ‏ ‏قَالَ ‏ ‏شُعْبَةُ ‏ ‏وَقَدْ قَالَهُمَا جَمِيعًا ‏","","",""],[13489,13489,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَبْدِ اللَّهِ بْنِ عَبْدِ اللَّهِ بْنِ جَبْرٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْتَسِلُ بِخَمْسَةِ ‏ ‏مَكَاكِيكَ ‏ ‏وَكَانَ يَتَوَضَّأُ ‏ ‏بِالْمَكُّوكِ ‏","","",""],[13490,13490,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏يَحْيَى بْنِ أَبِي إِسْحَاقَ ‏ ‏قَالَ ‏ ‏سَأَلْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏عَنْ الصَّلَاةِ فِي السَّفَرِ فَقَالَ ‏ ‏خَرَجْنَا مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏فَكُنَّا نُصَلِّي رَكْعَتَيْنِ حَتَّى نَرْجِعَ إِلَى ‏ ‏الْمَدِينَةِ ‏ ‏فَسَأَلْتُهُ كَمْ أَقَمْتُمْ ‏ ‏بِمَكَّةَ ‏ ‏قَالَ عَشَرَةَ أَيَّامٍ قُلْتُ فَبِمَ ‏ ‏أَهَلَّ ‏ ‏رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَبَّيْكَ بِعُمْرَةٍ وَحَجَّةٍ ‏","","",""],[13491,13491,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏حُمَيْدٌ الطَّوِيلُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏سَمِعْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏لَبَّيْكَ بِعُمْرَةٍ وَحَجَّةٍ مَعًا ‏ ‏أَوْ قَالَ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[13492,13492,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ الطَّوِيلِ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏دَعَا رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غُلَامًا مِنَّا ‏ ‏فَحَجَمَهُ ‏ ‏فَأَعْطَاهُ أَجْرَهُ ‏ ‏صَاعًا ‏ ‏أَوْ ‏ ‏صَاعَيْنِ ‏ ‏وَكَلَّمَ ‏ ‏مَوَالِيَهُ ‏ ‏أَنْ يُخَفِّفُوا عَنْهُ مِنْ ضَرِيبَتِهِ ‏","","",""],[13493,13493,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَنَتَ ‏ ‏شَهْرًا يَدْعُو عَلَى أَحْيَاءٍ مِنْ ‏ ‏الْعَرَبِ ‏ ‏رِعْلٍ ‏ ‏وَبَنِي لِحْيَانَ ‏ ‏وَعُصَيَّةَ ‏ ‏وَذَكْوَانَ ‏ ‏فِي صَلَاةِ الصُّبْحِ ‏","","",""],[13494,13494,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏حَنْظَلَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَنَتَ ‏ ‏شَهْرًا بَعْدَ الرُّكُوعِ ‏","","",""],[13495,13495,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏لَا يَرْفَعُ يَدَيْهِ فِي شَيْءٍ مِنْ الدُّعَاءِ إِلَّا عِنْدَ ‏ ‏الِاسْتِسْقَاءِ ‏ ‏حَتَّى يُرَى بَيَاضُ إِبْطَيْهِ ‏","","",""],[13496,13496,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَنْ نَسِيَ صَلَاةً أَوْ نَامَ عَنْهَا فَإِنَّ كَفَّارَتَهَا أَنْ يُصَلِّيَهَا إِذَا ذَكَرَهَا ‏","","",""],[13497,13497,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏عَلِيِّ بْنِ زَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏إِنْ كَانَ الْمُؤَذِّنُ لَيُؤَذِّنُ عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَنُرَى أَنَّهَا الْإِقَامَةُ مِنْ كَثْرَةِ مَنْ يَقُومُ فَيُصَلِّي الرَّكْعَتَيْنِ قَبْلَ الْمَغْرِبِ ‏","","",""],[13498,13498,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏حَمْزَةَ الضَّبِّيَّ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏مَا صَلَّيْتُ ‏ ‏يَعْنِي وَرَاءَ رَجُلٍ أَوْ أَحَدٍ مِنْ النَّاسِ ‏ ‏أَخَفَّ صَلَاةً مِنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي تَمَامٍ ‏","","",""],[13499,13499,"","","‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ جَعْفَرٍ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ أُمَّهُ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏سَأَلَتْ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَتْ ‏ ‏الْمَرْأَةُ ‏ ‏تَرَى فِي مَنَامِهَا مَا يَرَى الرَّجُلُ فَقَالَ إِذَا رَأَتْ ذَلِكَ فِي مَنَامِهَا فَلْتَغْتَسِلْ فَقَالَتْ ‏ ‏أُمُّ سَلَمَةَ زَوْجُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاسْتَحْيَتْ أَوَيَكُونُ هَذَا يَا رَسُولَ اللَّهِ قَالَ نَعَمْ فَمِنْ أَيْنَ يَكُونُ الشَّبَهُ ‏ ‏مَاءُ ‏ ‏الرَّجُلِ أَبْيَضُ غَلِيظٌ ‏ ‏وَمَاءُ ‏ ‏الْمَرْأَةِ أَصْفَرُ رَقِيقٌ فَمِنْ أَيِّهِمَا سَبَقَ ‏ ‏أَوْ عَلَا ‏ ‏يَكُونُ الشَّبَهُ ‏","","",""],[13500,13500,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏انْطَلَقَ ‏ ‏حَارِثَةُ ‏ ‏ابْنُ عَمَّتِي يَوْمَ ‏ ‏بَدْرٍ ‏ ‏مَعَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏غُلَامًا ‏ ‏نَظَّارًا ‏ ‏مَا انْطَلَقَ لِلْقِتَالِ قَالَ فَأَصَابَهُ سَهْمٌ فَقَتَلَهُ قَالَ فَجَاءَتْ ‏ ‏أُمُّهُ ‏ ‏عَمَّتِي إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَتْ يَا رَسُولَ اللَّهِ ابْنِي ‏ ‏حَارِثَةُ ‏ ‏إِنْ يَكُنْ فِي الْجَنَّةِ أَصْبِرْ وَأَحْتَسِبْ وَإِلَّا ‏ ‏فَسَيَرَى اللَّهُ مَا أَصْنَعُ قَالَ يَا ‏ ‏أُمَّ حَارِثَةَ ‏ ‏إِنَّهَا جِنَانٌ كَثِيرَةٌ وَإِنَّ ‏ ‏حَارِثَةَ ‏ ‏فِي ‏ ‏الْفِرْدَوْسِ ‏ ‏الْأَعْلَى ‏","","",""],[13501,13501,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏مُبَارَكُ بْنُ فَضَالَةَ ‏ ‏حَدَّثَنَا ‏ ‏الْحَسَنُ ‏ ‏أَخْبَرَنِي ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏قَالَ ‏ ‏كُنْتُ عِنْدَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي بَيْتِهِ فَجَاءَ رَجُلٌ فَقَالَ يَا رَسُولَ اللَّهِ مَتَى السَّاعَةُ قَالَ ‏ ‏أَمَا إِنَّهَا قَائِمَةٌ فَمَا أَعْدَدْتَ لَهَا قَالَ وَاللَّهِ يَا رَسُولَ اللَّهِ مَا أَعْدَدْتُ لَهَا مِنْ كَثِيرِ عَمَلٍ غَيْرَ أَنِّي أُحِبُّ اللَّهَ وَرَسُولَهُ قَالَ فَإِنَّكَ مَعَ مَنْ أَحْبَبْتَ وَلَكَ مَا ‏ ‏احْتَسَبْتَ ‏ ‏قَالَ ثُمَّ قَامَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي فَلَمَّا قَضَى صَلَاتَهُ قَالَ أَيْنَ السَّائِلُ عَنْ السَّاعَةِ فَأُتِيَ بِالرَّجُلِ فَنَظَرَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَى الْبَيْتِ فَإِذَا ‏ ‏غُلَامٌ ‏ ‏مِنْ ‏ ‏دَوْسٍ ‏ ‏مِنْ ‏ ‏رَهْطِ ‏ ‏أَبِي هُرَيْرَةَ ‏ ‏يُقَالُ لَهُ ‏ ‏سَعْدُ بْنُ مَالِكٍ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَذَا الْغُلَامُ إِنْ طَالَ بِهِ عُمُرٌ لَمْ يَبْلُغْ بِهِ ‏ ‏الْهَرَمُ ‏ ‏حَتَّى تَقُومَ السَّاعَةُ ‏ ‏قَالَ ‏ ‏الْحَسَنُ ‏ ‏وَأَخْبَرَنِي ‏ ‏أَنَسٌ ‏ ‏أَنَّ الْغُلَامَ كَانَ يَوْمَئِذٍ مِنْ ‏ ‏أَقْرَانِي ‏","","",""],[13502,13502,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏إِبْرَاهِيمُ أَبُو إِسْمَاعِيلَ الْقَنَّادُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَرْوِيهِ عَنْ رَبِّهِ عَزَّ وَجَلَّ قَالَ يَقُولُ رَبُّكُمْ عَزَّ وَجَلَّ ‏ ‏إِذَا ‏ ‏تَلَقَّانِي ‏ ‏عَبْدِي شِبْرًا تَلَقَّيْتُهُ ذِرَاعًا وَإِذَا ‏ ‏تَلَقَّانِي ‏ ‏ذِرَاعًا تَلَقَّيْتُهُ ‏ ‏بَاعًا ‏ ‏وَإِذَا ‏ ‏تَلَقَّانِي ‏ ‏يَمْشِي تَلَقَّيْتُهُ ‏ ‏أُهَرْوِلُ ‏","","",""],[13503,13503,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ يَعْنِي الْعَطَّارَ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بُعِثْتُ أَنَا وَالسَّاعَةُ كَهَاتَيْنِ ‏ ‏وَأَوْمَأَ ‏ ‏عَفَّانُ ‏ ‏بِالسَّبَّابَةِ وَالْوُسْطَى ‏","","",""],[13504,13504,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏حَارِثَةُ ‏ ‏أُصِيبَ يَوْمَ ‏ ‏بَدْرٍ ‏ ‏فَقَالَتْ ‏ ‏أُمُّ حَارِثَةَ ‏ ‏يَا نَبِيَّ اللَّهِ إِنْ كَانَ ابْنِي ‏ ‏أَصَابَ ‏ ‏الْجَنَّةَ وَإِلَّا أَجْهَدْتُ عَلَيْهِ بِالْبُكَاءِ قَالَ يَا ‏ ‏أُمَّ حَارِثَةَ ‏ ‏إِنَّهَا جِنَانٌ كَثِيرَةٌ فِي جَنَّةٍ وَإِنَّ ‏ ‏حَارِثَةَ ‏ ‏أَصَابَ ‏ ‏الْفِرْدَوْسَ ‏ ‏الْأَعْلَى ‏","","",""],[13505,13505,"","","‏ ‏قَالَ ‏ ‏أَبِي ‏ ‏وَبِهَذَا الْإِسْنَادِ وَاللَّفْظِ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏لَا ‏ ‏تَدَابَرُوا ‏ ‏وَلَا تَبَاغَضُوا وَلَا تَحَاسَدُوا وَكُونُوا عِبَادَ اللَّهِ إِخْوَانًا ‏","","",""],[13506,13506,"","","‏ ‏حَدَّثَنِي ‏ ‏قَالَ ‏ ‏وَإِنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏تَرَاصُّوا صُفُوفَكُمْ وَقَارِبُوا بَيْنَهَا ‏ ‏وَحَاذُوا ‏ ‏بَيْنَ الْأَعْنَاقِ فَوَالَّذِي نَفْسُ ‏ ‏مُحَمَّدٍ ‏ ‏بِيَدِهِ إِنِّي لَأَرَى الشَّيْطَانَ يَدْخُلُ مِنْ ‏ ‏خَلَلِ ‏ ‏الصَّفِّ كَأَنَّهُ ‏ ‏الْحَذَفُ ‏","","",""],[13507,13507,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ لَا يَظْلِمُ الْمُؤْمِنَ حَسَنَةً يُثَابُ عَلَيْهَا الرِّزْقَ فِي الدُّنْيَا ‏ ‏وَيُجْزَى بِهَا فِي الْآخِرَةِ قَالَ وَأَمَّا الْكَافِرُ فَيُطْعَمُ بِحَسَنَاتِهِ فِي الدُّنْيَا حَتَّى إِذَا ‏ ‏أَفْضَى ‏ ‏إِلَى الْآخِرَةِ لَمْ يَكُنْ لَهُ حَسَنَةٌ يُعْطَى بِهَا خَيْرًا ‏","","",""],[13508,13508,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏سِمَاكُ بْنُ حَرْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ ‏ ‏بِبَرَاءَةٌ ‏ ‏مَعَ ‏ ‏أَبِي بَكْرٍ ‏ ‏إِلَى أَهْلِ ‏ ‏مَكَّةَ ‏ ‏قَالَ ثُمَّ دَعَاهُ فَبَعَثَ بِهَا ‏ ‏عَلِيًّا ‏ ‏قَالَ ‏ ‏لَا يُبَلِّغُهَا إِلَّا رَجُلٌ مِنْ أَهْلِي ‏","","",""],[13509,13509,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَيُّوبُ ‏ ‏عَنْ ‏ ‏أَبِي قِلَابَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى ‏ ‏يَتَبَاهَى النَّاسُ فِي الْمَسَاجِدِ ‏","","",""],[13510,13510,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏نُوحُ بْنُ قَيْسٍ ‏ ‏حَدَّثَنَا ‏ ‏الْأَشْعَثُ بْنُ جَابِرٍ الْحَدَّانِيُّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ قَالَ رَبُّكُمْ عَزَّ وَجَلَّ ‏ ‏مَنْ أَذْهَبْتُ كَرِيمَتَيْهِ ثُمَّ صَبَرَ ‏ ‏وَاحْتَسَبَ ‏ ‏كَانَ ثَوَابُهُ الْجَنَّةَ ‏","","",""],[13511,13511,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَارِثِ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏قِرَامٌ ‏ ‏لِعَائِشَةَ ‏ ‏قَدْ سَتَرَتْ بِهِ جَانِبَ بَيْتِهَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَمِيطِي ‏ ‏قِرَامَكِ ‏ ‏هَذَا عَنِّي فَإِنَّهُ لَا يَزَالُ تَصَاوِيرُهُ تَعْرِضُ لِي فِي صَلَاتِي ‏","","",""],[13512,13512,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏خَلَفُ بْنُ خَلِيفَةَ ‏ ‏حَدَّثَنَا ‏ ‏حَفْصُ بْنُ عُمَرَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ مِنْ دُعَاءِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ عِلْمٍ لَا يَنْفَعُ وَقَلْبٍ لَا يَخْشَعُ وَدُعَاءٍ لَا يُسْمَعُ وَنَفْسٍ لَا تَشْبَعُ اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ هَؤُلَاءِ الْأَرْبَعِ ‏","","",""],[13513,13513,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏مُحَمَّدُ بْنُ دِينَارٍ ‏ ‏حَدَّثَنِي ‏ ‏يَحْيَى بْنُ يَزِيدَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُئِلَ عَنْ رَجُلٍ كَانَتْ تَحْتَهُ امْرَأَةٌ فَطَلَّقَهَا ثَلَاثًا فَتَزَوَّجَتْ بَعْدَهُ رَجُلًا فَطَلَّقَهَا قَبْلَ أَنْ يَدْخُلَ بِهَا أَتَحِلُّ لِزَوْجِهَا الْأَوَّلِ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا حَتَّى يَكُونَ الْآخَرُ قَدْ ذَاقَ مِنْ ‏ ‏عُسَيْلَتِهَا ‏ ‏وَذَاقَتْ مِنْ ‏ ‏عُسَيْلَتِهِ ‏","","",""],[13514,13514,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏جَعْفَرُ بْنُ مَعْبَدٍ ‏ ‏قَالَ ‏ ‏ذَهَبْتُ إِلَى ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَا ‏ ‏وَحُمَيْدُ بْنُ عَبْدِ الرَّحْمَنِ ‏ ‏قَالَ فَسَمِعْتُ ‏ ‏أَنَسًا ‏ ‏قَالَ كُنَّا ‏ ‏إِذَا ‏ ‏بَايَعْنَا ‏ ‏رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُلَقِّنُنَا هُوَ فِيمَا اسْتَطَعْتَ ‏","","",""],[13515,13515,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏أَبِي مُعَاذٍ عَطَاءِ بْنِ أَبِي مَيْمُونٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسًا ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذَا خَرَجَ ‏ ‏لِحَاجَتِهِ ‏ ‏نَجِيءُ أَنَا وَغُلَامٌ مِنَّا ‏ ‏بِإِدَاوَةٍ ‏ ‏مِنْ مَاءٍ ‏","","",""],[13516,13516,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ إِسْرَائِيلَ ‏ ‏سَأَلْتُ أَبِي عَنْهُ فَقَالَ ‏ ‏شَيْخٌ ثِقَةٌ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو إِسْحَاقَ يَعْنِي الْفَزَارِيَّ ‏ ‏عَنِ ‏ ‏الْأَوْزَاعِيِّ ‏ ‏عَنْ ‏ ‏إِسْحَاقَ بْنِ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏بَعَثَتْنِي أُمِّي إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِشَيْءٍ فَرَأَيْتُهُ ‏ ‏قَائِمًا فِي يَدِهِ ‏ ‏الْمِيسَمُ ‏ ‏يَسِمُ ‏ ‏الصَّدَقَةَ ‏","","",""],[13517,13517,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ أُخْتَ ‏ ‏الرُّبَيِّعِ أُمَّ حَارِثَةَ ‏ ‏جَرَحَتْ إِنْسَانًا ‏ ‏فَاخْتَصَمُوا ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏الْقِصَاصُ ‏ ‏الْقِصَاصُ ‏ ‏فَقَالَتْ ‏ ‏أُمُّ الرُّبَيِّعِ ‏ ‏يَا رَسُولَ اللَّهِ ‏ ‏أَيُقْتَصُّ ‏ ‏مِنْ فُلَانَةَ لَا وَاللَّهِ لَا ‏ ‏يُقْتَصُّ ‏ ‏مِنْهَا أَبَدًا قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سُبْحَانَ اللَّهِ يَا ‏ ‏أُمَّ رُبَيِّعٍ ‏ ‏كِتَابُ اللَّهِ قَالَتْ لَا وَاللَّهِ لَا ‏ ‏يُقْتَصُّ ‏ ‏مِنْهَا أَبَدًا قَالَ فَمَا زَالَتْ حَتَّى قَبِلُوا مِنْهَا ‏ ‏الدِّيَةَ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ مِنْ عِبَادِ اللَّهِ مَنْ لَوْ أَقْسَمَ عَلَى اللَّهِ ‏ ‏لَأَبَرَّهُ ‏","","",""],[13518,13518,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَجُلًا سَأَلَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَعْطَاهُ غَنَمًا بَيْنَ جَبَلَيْنِ فَأَتَى قَوْمَهُ فَقَالَ أَيْ قَوْمِ أَسْلِمُوا فَوَاللَّهِ ‏ ‏إِنَّ ‏ ‏مُحَمَّدًا ‏ ‏لَيُعْطِي عَطَاءَ مَنْ لَا يَخَافُ ‏ ‏الْفَاقَةَ ‏ ‏وَإِنْ كَانَ الرَّجُلُ لَيَجِيءُ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا يُرِيدُ إِلَّا الدُّنْيَا فَمَا يُمْسِي حَتَّى يَكُونَ دِينُهُ أَحَبَّ إِلَيْهِ ‏ ‏أَوْ أَعَزَّ عَلَيْهِ ‏ ‏مِنْ الدُّنْيَا بِمَا فِيهَا ‏","","",""],[13519,13519,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏حُفَّتْ ‏ ‏الْجَنَّةُ بِالْمَكَارِهِ ‏ ‏وَحُفَّتْ ‏ ‏النَّارُ بِالشَّهَوَاتِ ‏","","",""],[13520,13520,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏وَحُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَرَّ بِمَقْبَرَةٍ ‏ ‏لِبَنِي النَّجَّارِ ‏ ‏فِي ‏ ‏حَائِطٍ ‏ ‏وَهُوَ عَلَى بَغْلَةٍ ‏ ‏شَهْبَاءَ ‏ ‏فَإِذَا هُوَ بِقَبْرٍ يُعَذَّبُ ‏ ‏فَحَاصَتْ ‏ ‏الْبَغْلَةُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَوْلَا أَنْ لَا تَدَافَنُوا لَسَأَلْتُ اللَّهَ أَنْ يُسْمِعَكُمْ عَذَابَ الْقَبْرِ ‏","","",""],[13521,13521,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏وَبَهْزٌ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَعَا ‏ ‏أُبَيًّا ‏ ‏فَقَالَ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ أَمَرَنِي أَنْ أَقْرَأَ عَلَيْكَ فَقَالَ سَمَّانِي لَكَ فَقَالَ اللَّهُ سَمَّاكَ لِي فَجَعَلَ يَبْكِي ‏","","",""],[13522,13522,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ نَفْسٍ ‏ ‏مَنْفُوسَةٍ ‏ ‏تَمُوتُ لَهَا عِنْدَ اللَّهِ خَيْرٌ يَسُرُّهَا أَنْ تَرْجِعَ إِلَى الدُّنْيَا إِلَّا الشَّهِيدَ فَإِنَّهُ يَسُرُّهُ أَنْ يَرْجِعَ إِلَى الدُّنْيَا فَيُقْتَلَ لِمَا يَرَى مِنْ فَضْلِ الشَّهَادَةِ ‏","","",""],[13523,13523,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يُصَلِّي نَحْوَ ‏ ‏بَيْتِ الْمَقْدِسِ ‏ ‏فَنَزَلَتْ ‏ { ‏قَدْ نَرَى تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَاهَا فَوَلِّ وَجْهَكَ شَطْرَ ‏ ‏الْمَسْجِدِ الْحَرَامِ ‏ } ‏فَمَرَّ رَجُلٌ مِنْ ‏ ‏بَنِي سَلَمَةَ ‏ ‏وَهُمْ رُكُوعٌ فِي صَلَاةِ الْفَجْرِ وَقَدْ صَلَّوْا رَكْعَةً فَنَادَى أَلَا إِنَّ الْقِبْلَةَ قَدْ حُوِّلَتْ أَلَا إِنَّ الْقِبْلَةَ قَدْ حُوِّلَتْ إِلَى ‏ ‏الْكَعْبَةِ ‏ ‏قَالَ فَمَالُوا كَمَا هُمْ نَحْوَ الْقِبْلَةِ ‏","","",""],[13524,13524,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ لِأَهْلِ الْجَنَّةِ سُوقًا ‏ ‏يَأْتُونَهَا كُلَّ جُمُعَةٍ فِيهَا ‏ ‏كُثْبَانُ ‏ ‏الْمِسْكِ ‏ ‏فَإِذَا خَرَجُوا إِلَيْهَا هَبَّتْ الرِّيحُ ‏ ‏قَالَ ‏ ‏حَمَّادٌ ‏ ‏أَحْسِبُهُ قَالَ شَمَالِيٌّ ‏ ‏قَالَ فَتَمْلَأُ وُجُوهَهُمْ وَثِيَابَهُمْ وَبُيُوتَهُمْ مِسْكًا فَيَزْدَادُونَ حُسْنًا وَجَمَالًا قَالَ فَيَأْتُونَ أَهْلِيهِمْ فَيَقُولُونَ لَقَدْ ازْدَدْتُمْ بَعْدَنَا حُسْنًا وَجَمَالًا وَيَقُولُونَ لَهُنَّ وَأَنْتُمْ قَدْ ازْدَدْتُمْ بَعْدَنَا حُسْنًا وَجَمَالًا ‏","","",""],[13525,13525,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏لَنْ تَنَالُوا ‏ ‏الْبِرَّ ‏ ‏حَتَّى تُنْفِقُوا مِمَّا تُحِبُّونَ ‏} ‏قَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏يَا رَسُولَ اللَّهِ أَرَى رَبَّنَا يَسْأَلُنَا مِنْ أَمْوَالِنَا وَإِنِّي أُشْهِدُكَ أَنِّي قَدْ جَعَلْتُ أَرْضِي ‏ ‏بَيْرُحَاءَ ‏ ‏لِلَّهِ عَزَّ وَجَلَّ قَالَ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اجْعَلْهَا فِي قَرَابَتِكَ فَقَسَمَهَا بَيْنَ ‏ ‏حَسَّانَ بْنِ ثَابِتٍ ‏ ‏وَأُبَيِّ بْنِ كَعْبٍ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏وَقَالَ ‏ ‏يَزِيدُ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏بَرِيحَا ‏ ‏و قَالَ ‏ ‏عَفَّانُ ‏ ‏سَأَلْتُ عَنْهَا غَيْرَ وَاحِدٍ مِنْ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏فَزَعَمُوا أَنَّهَا ‏ ‏بَيْرُحَاءُ ‏ ‏وَأَنَّ ‏ ‏بَيْرَحَا ‏ ‏لَيْسَ بِشَيْءٍ ‏","","",""],[13526,13526,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَلَّامُ أَبُو الْمُنْذِرِ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حُبِّبَ إِلَيَّ مِنْ الدُّنْيَا النِّسَاءُ وَالطِّيبُ وَجُعِلَتْ ‏ ‏قُرَّةُ ‏ ‏عَيْنِي فِي الصَّلَاةِ ‏","","",""],[13527,13527,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنِ ‏ ‏الْجَعْدِ أَبِي عُثْمَانَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ لَهُ ‏ ‏يَا بُنَيَّ ‏","","",""],[13528,13528,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَعِيدُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏إِنِّي لَأَعْرِفُ الْيَوْمَ ذُنُوبًا هِيَ أَدَقُّ فِي أَعْيُنِكُمْ مِنْ الشَّعْرِ كُنَّا نَعُدُّهَا عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مِنْ الْكَبَائِرِ ‏","","",""],[13529,13529,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏عَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَمُرُّ بِبَابِ ‏ ‏فَاطِمَةَ ‏ ‏سِتَّةَ أَشْهُرٍ إِذَا خَرَجَ إِلَى صَلَاةِ الْفَجْرِ يَقُولُ ‏ ‏الصَّلَاةُ يَا أَهْلَ الْبَيْتِ ‏ { ‏إِنَّمَا يُرِيدُ اللَّهُ لِيُذْهِبَ عَنْكُمْ ‏ ‏الرِّجْسَ ‏ ‏أَهْلَ الْبَيْتِ وَيُطَهِّرَكُمْ تَطْهِيرًا ‏}","","",""],[13530,13530,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏وَأَبُو عِمْرَانَ الْجَوْنِيُّ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يَخْرُجُ أَرْبَعَةٌ مِنْ النَّارِ ‏ ‏قَالَ ‏ ‏أَبُو عِمْرَانَ ‏ ‏أَرْبَعَةٌ ‏ ‏قَالَ ‏ ‏ثَابِتٌ ‏ ‏رَجُلَانِ ‏ ‏فَيُعْرَضُونَ عَلَى اللَّهِ عَزَّ وَجَلَّ ثُمَّ يُؤْمَرُ بِهِمَا إِلَى النَّارِ قَالَ فَيَلْتَفِتُ أَحَدُهُمْ فَيَقُولُ أَيْ رَبِّ قَدْ كُنْتُ أَرْجُو إِذَا أَخْرَجْتَنِي مِنْهَا أَنْ لَا تُعِيدَنِي فِيهَا ‏ ‏فَيُنْجِيهِ اللَّهُ مِنْهَا عَزَّ وَجَلَّ ‏","","",""],[13531,13531,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏بَيْنَمَا النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَعَ ‏ ‏امْرَأَةٍ مِنْ نِسَائِهِ ‏ ‏إِذْ مَرَّ بِهِ رَجُلٌ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَا فُلَانُ هَذِهِ فُلَانَةُ زَوْجَتِي فَقَالَ الرَّجُلُ يَا رَسُولَ اللَّهِ مَنْ كُنْتُ أَظُنُّ بِهِ فَإِنِّي لَمْ أَكُنْ لِأَظُنَّ بِكَ قَالَ ‏ ‏إِنَّ الشَّيْطَانَ يَجْرِي مِنْ ابْنِ ‏ ‏آدَمَ ‏ ‏مَجْرَى الدَّمِ ‏","","",""],[13532,13532,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اسْتَقْبَلَهُ ذَاتَ يَوْمٍ صِبْيَانُ ‏ ‏الْأَنْصَارِ ‏ ‏وَالْإِمَاءُ ‏ ‏فَقَالَ وَاللَّهِ ‏ ‏إِنِّي لَأُحِبُّكُمْ ‏","","",""],[13533,13533,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ لَهُ ‏ ‏حَادٍ ‏ ‏جَيِّدُ ‏ ‏الْحُدَاءِ ‏ ‏وَكَانَ ‏ ‏حَادِيَ ‏ ‏الرِّجَالِ وَكَانَ ‏ ‏أَنْجَشَةُ ‏ ‏يَحْدُو ‏ ‏بِأَزْوَاجِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَلَمَّا ‏ ‏حَدَا ‏ ‏أَعْنَقَتْ الْإِبِلُ فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيْحَكَ ‏ ‏يَا ‏ ‏أَنْجَشَةُ ‏ ‏رُوَيْدًا سَوْقَكَ ‏ ‏بِالْقَوَارِيرِ ‏","","",""],[13534,13534,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏نَفَرًا ‏ ‏مِنْ ‏ ‏أَصْحَابِ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَأَلُوا أَزْوَاجَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ عَمَلِهِ فِي السِّرِّ فَقَالَ بَعْضُهُمْ لَا أَتَزَوَّجُ النِّسَاءَ وَقَالَ بَعْضُهُمْ لَا آكُلُ اللَّحْمَ وَقَالَ بَعْضُهُمْ لَا أَنَامُ عَلَى فِرَاشٍ وَقَالَ بَعْضُهُمْ أَصُومُ وَلَا أُفْطِرُ فَقَامَ فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ مَا بَالُ أَقْوَامٍ قَالُوا كَذَا وَكَذَا وَلَكِنِّي ‏ ‏أُصَلِّي وَأَنَامُ وَأَصُومُ وَأُفْطِرُ وَأَتَزَوَّجُ النِّسَاءَ فَمَنْ رَغِبَ عَنْ سُنَّتِي فَلَيْسَ مِنِّي ‏","","",""],[13535,13535,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ امْرَأَةً كَانَ فِي ‏ ‏عَقْلِهَا ‏ ‏شَيْءٌ فَقَالَتْ يَا رَسُولَ اللَّهِ إِنَّ لِي حَاجَةً فَقَالَ يَا أُمَّ فُلَانٍ انْظُرِي إِلَى أَيِّ الطَّرِيقِ شِئْتِ ‏ ‏فَقَامَ مَعَهَا ‏ ‏يُنَاجِيهَا ‏ ‏حَتَّى قَضَتْ حَاجَتَهَا ‏","","",""],[13536,13536,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كُنَّا نَتَحَدَّثُ أَنَّهُ ‏ ‏لَا تَقُومُ السَّاعَةُ حَتَّى لَا تُمْطِرَ السَّمَاءُ وَلَا تُنْبِتَ الْأَرْضُ وَحَتَّى يَكُونَ لِخَمْسِينَ امْرَأَةً ‏ ‏الْقَيِّمُ ‏ ‏الْوَاحِدُ وَحَتَّى أَنَّ الْمَرْأَةَ لَتَمُرُّ ‏ ‏بِالْبَعْلِ ‏ ‏فَيَنْظُرُ إِلَيْهَا فَيَقُولُ لَقَدْ كَانَ لِهَذِهِ مَرَّةً رَجُلٌ ‏ ‏ذَكَرَهُ ‏ ‏حَمَّادٌ ‏ ‏مَرَّةً هَكَذَا وَقَدْ ذَكَرَهُ عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يَشُكُّ فِيهِ وَقَدْ قَالَ أَيْضًا عَنْ ‏ ‏أَنَسٍ ‏ ‏عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِيمَا يَحْسِبُ ‏","","",""],[13537,13537,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ أَهْلَ ‏ ‏الْيَمَنِ ‏ ‏لَمَّا قَدِمُوا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالُوا ابْعَثْ مَعَنَا رَجُلًا يُعَلِّمُنَا السُّنَّةَ وَالْإِسْلَامَ قَالَ فَأَخَذَ بِيَدِ ‏ ‏أَبِي عُبَيْدَةَ بْنِ الْجَرَّاحِ ‏ ‏وَقَالَ ‏ ‏هَذَا أَمِينُ هَذِهِ الْأُمَّةِ ‏","","",""],[13538,13538,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏كَانَتْ مَعَ ‏ ‏أَبِي طَلْحَةَ ‏ ‏يَوْمَ ‏ ‏حُنَيْنٍ ‏ ‏فَإِذَا مَعَ ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏خِنْجَرٌ فَقَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏مَا هَذَا مَعَكِ يَا ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏فَقَالَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏اتَّخَذْتُهُ إِنْ دَنَا مِنِّي أَحَدٌ مِنْ الْكُفَّارِ ‏ ‏أَبْعَجُ ‏ ‏بِهِ بَطْنَهُ فَقَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏يَا نَبِيَّ اللَّهِ أَلَا تَسْمَعُ مَا تَقُولُ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏تَقُولُ كَذَا وَكَذَا فَقَالَتْ يَا رَسُولَ اللَّهِ أَقُتِلَ مَنْ بَعْدَنَا مِنْ ‏ ‏الطُّلَقَاءِ ‏ ‏انْهَزَمُوا بِكَ يَا رَسُولَ اللَّهِ فَقَالَ يَا ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏إِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ كَفَانَا وَأَحْسَنَ ‏","","",""],[13539,13539,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أُعْطِيَ ‏ ‏يُوسُفُ ‏ ‏عَلَيْهِ الصَّلَاة وَالسَّلَامُ ‏ ‏شَطْرَ ‏ ‏الْحُسْنِ ‏","","",""],[13540,13540,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏وَثَابِتٌ ‏ ‏وَحُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏رَضِيَ اللَّهُ عَنْهُمْ ‏ ‏كَانُوا ‏ ‏يَسْتَفْتِحُونَ الْقِرَاءَةَ بْ ‏ { ‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏} ‏إِلَّا أَنَّ ‏ ‏حُمَيْدًا ‏ ‏لَمْ يَذْكُرْ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[13541,13541,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏رَأَيْتُ كَأَنِّي فِي دَارِ ‏ ‏عُقْبَةَ بْنِ رَافِعٍ ‏ ‏فَأُتِينَا بِرُطَبٍ مِنْ رُطَبِ ‏ ‏ابْنِ طَابٍ ‏ ‏فَأَوَّلْتُ ‏ ‏أَنَّ الرِّفْعَةَ لَنَا فِي الدُّنْيَا ‏ ‏وَالْعَاقِبَةَ ‏ ‏فِي الْآخِرَةِ وَأَنَّ دِينَنَا قَدْ طَابَ ‏","","",""],[13542,13542,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اسْتَوُوا فَوَاللَّهِ إِنِّي لَأَرَاكُمْ مِنْ خَلْفِي كَمَا أَرَاكُمْ مِنْ بَيْنِ يَدَيَّ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏حُمَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏بِمِثْلِهِ غَيْرَ أَنَّهُ قَالَ اسْتَوُوا وَتَرَاصُّوا ‏","","",""],[13543,13543,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَقَدْ أُخِفْتُ فِي اللَّهِ عَزَّ وَجَلَّ وَمَا يَخَافُ أَحَدٌ وَلَقَدْ أُوذِيتُ فِي اللَّهِ وَمَا ‏ ‏يُؤْذَى أَحَدٌ وَلَقَدْ أَتَتْ عَلَيَّ ثَلَاثُونَ مِنْ بَيْنِ يَوْمٍ وَلَيْلَةٍ وَمَا لِي وَلَا ‏ ‏لِبِلَالٍ ‏ ‏طَعَامٌ يَأْكُلُهُ ‏ ‏ذُو كَبِدٍ ‏ ‏إِلَّا شَيْءٌ ‏ ‏يُوَارِيهِ ‏ ‏إِبِطُ ‏ ‏بِلَالٍ ‏","","",""],[13544,13544,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏وَعَلِيُّ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ الْمُشْرِكِينَ لَمَّا ‏ ‏رَهِقُوا ‏ ‏النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَهُوَ فِي سَبْعَةٍ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏وَرَجُلَيْنِ مِنْ ‏ ‏قُرَيْشٍ ‏ ‏قَالَ ‏ ‏مَنْ يَرُدُّهُمْ عَنَّا وَهُوَ رَفِيقِي فِي الْجَنَّةِ فَجَاءَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏فَقَاتَلَ حَتَّى قُتِلَ فَلَمَّا ‏ ‏أَرْهَقُوهُ ‏ ‏أَيْضًا قَالَ مَنْ يَرُدُّهُمْ عَنِّي وَهُوَ رَفِيقِي فِي الْجَنَّةِ حَتَّى قُتِلَ السَّبْعَةُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لِصَاحِبِهِ مَا أَنْصَفْنَا إِخْوَانَنَا ‏","","",""],[13545,13545,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادُ بْنُ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏وَثَابِتٌ ‏ ‏وَحُمَيْدٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏غَلَا السِّعْرُ ‏ ‏بِالْمَدِينَةِ ‏ ‏عَلَى عَهْدِ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ النَّاسُ يَا رَسُولَ اللَّهِ غَلَا السِّعْرُ سَعِّرْ لَنَا فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّ اللَّهَ هُوَ الْمُسَعِّرُ الْقَابِضُ الْبَاسِطُ الرَّزَّاقُ إِنِّي لَأَرْجُو أَنْ أَلْقَى اللَّهَ عَزَّ وَجَلَّ وَلَيْسَ أَحَدٌ مِنْكُمْ يَطْلُبُنِي بِمَظْلَمَةٍ فِي دَمٍ وَلَا مَالٍ ‏","","",""],[13546,13546,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏أَبَا طَلْحَةَ ‏ ‏كَانَ يَرْمِي بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏أُحُدٍ ‏ ‏وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏خَلْفَهُ ‏ ‏يَتَتَرَّسُ ‏ ‏بِهِ وَكَانَ رَامِيًا وَكَانَ ‏ ‏إِذَا رَمَى رَفَعَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏شَخْصَهُ ‏ ‏يَنْظُرُ أَيْنَ يَقَعُ سَهْمُهُ وَيَرْفَعُ ‏ ‏أَبُو طَلْحَةَ ‏ ‏صَدْرَهُ وَيَقُولُ هَكَذَا بِأَبِي أَنْتَ وَأُمِّي يَا رَسُولَ اللَّهِ ‏ ‏لَا يُصِيبُكَ سَهْمٌ ‏ ‏نَحْرِي ‏ ‏دُونَ ‏ ‏نَحْرِكَ ‏ ‏وَكَانَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏يَسُوقُ نَفْسَهُ بَيْنَ يَدَيْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَيَقُولُ إِنِّي ‏ ‏جَلْدٌ ‏ ‏يَا رَسُولَ اللَّهِ فَوَجِّهْنِي فِي حَوَائِجِكَ وَمُرْنِي بِمَا شِئْتَ ‏","","",""],[13547,13547,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَمَّا أَرَادَ أَنْ يَحْلِقَ رَأْسَهُ ‏ ‏بِمِنًى ‏ ‏أَخَذَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏شِقَّ ‏ ‏رَأْسِهِ فَحَلَقَ ‏ ‏الْحَجَّامُ ‏ ‏فَجَاءَ بِهِ إِلَى ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏وَكَانَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏تَجْعَلُهُ فِي ‏ ‏مِسْكِهَا ‏ ‏وَكَانَ يَجِيءُ ‏ ‏فَيَقِيلُ ‏ ‏عِنْدَهَا عَلَى ‏ ‏نِطْعٍ ‏ ‏وَكَانَ ‏ ‏مِعْرَاقًا ‏ ‏فَجَاءَ ذَاتَ يَوْمٍ فَجَعَلَتْ ‏ ‏تَسْلُتُ ‏ ‏الْعَرَقَ وَتَجْعَلُهُ فِي ‏ ‏قَارُورَةٍ ‏ ‏لَهَا فَاسْتَيْقَظَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ مَا تَجْعَلِينَ يَا ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏قَالَتْ يَا نَبِيَّ اللَّهِ ‏ ‏عَرَقُكَ أُرِيدُ أَنْ ‏ ‏أَدُوفَ ‏ ‏بِهِ طِيبِي ‏","","",""],[13548,13548,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏لَمَّا نَزَلَتْ ‏ { ‏يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَرْفَعُوا أَصْوَاتَكُمْ فَوْقَ صَوْتِ النَّبِيِّ ‏} ‏قَالَ قَعَدَ ‏ ‏ثَابِتُ بْنُ قَيْسٍ ‏ ‏فِي بَيْتِهِ فَفَقَدَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ ‏ ‏لِسَعْدِ بْنِ مُعَاذٍ ‏ ‏يَا ‏ ‏أَبَا عَمْرٍو ‏ ‏مَا شَأْنُ ‏ ‏ثَابِتِ بْنِ قَيْسٍ ‏ ‏لَا يُرَى ‏ ‏أَاشْتَكَى ‏ ‏فَقَالَ مَا عَلِمْتُ لَهُ بِمَرَضٍ وَإِنَّهُ لَجَارِي فَدَخَلَ عَلَيْهِ ‏ ‏سَعْدٌ ‏ ‏فَذَكَرَ لَهُ قَوْلَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ قَدْ عَلِمْتَ أَنِّي كُنْتُ مِنْ أَشَدِّكُمْ رَفْعَ صَوْتٍ عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ نَزَلَتْ هَذِهِ الْآيَةُ وَقَدْ هَلَكْتُ أَنَا مِنْ أَهْلِ النَّارِ فَذَكَرَ ذَلِكَ ‏ ‏سَعْدٌ ‏ ‏لِلنَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ بَلْ هُوَ مِنْ أَهْلِ الْجَنَّةِ ‏","","",""],[13549,13549,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ نَاسًا مِنْ ‏ ‏عُرَيْنَةَ ‏ ‏قَدِمُوا ‏ ‏الْمَدِينَةَ ‏ ‏فَاجْتَوَوْهَا ‏ ‏فَبَعَثَ بِهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فِي إِبِلِ ‏ ‏الصَّدَقَةِ ‏ ‏وَقَالَ ‏ ‏اشْرَبُوا مِنْ أَلْبَانِهَا وَأَبْوَالِهَا فَقَتَلُوا ‏ ‏رَاعِيَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَاسْتَاقُوا الْإِبِلَ وَارْتَدُّوا عَنْ الْإِسْلَامِ فَأُتِيَ بِهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَطَعَ أَيْدِيَهُمْ وَأَرْجُلَهُمْ مِنْ ‏ ‏خِلَافٍ ‏ ‏وَسَمَرَ ‏ ‏أَعْيُنَهُمْ وَأَلْقَاهُمْ ‏ ‏بِالْحَرَّةِ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏قَدْ كُنْتُ أَرَى أَحَدَهُمْ ‏ ‏يَكْدُمُ ‏ ‏الْأَرْضَ بِفِيهِ حَتَّى مَاتُوا ‏ ‏وَرُبَّمَا قَالَ ‏ ‏حَمَّادٌ ‏ ‏يَكْدُمُ ‏ ‏الْأَرْضَ بِفِيهِ حَتَّى مَاتُوا ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏وَهَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏بِنَحْوِ حَدِيثِ ‏ ‏حَمَّادٍ ‏","","",""],[13550,13550,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏أَبَا بَكْرٍ ‏ ‏كَانَ ‏ ‏رَدِيفَ ‏ ‏رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَيْنَ ‏ ‏مَكَّةَ ‏ ‏وَالْمَدِينَةِ ‏ ‏وَكَانَ ‏ ‏أَبُو بَكْرٍ ‏ ‏يَخْتَلِفُ ‏ ‏إِلَى ‏ ‏الشَّامِ ‏ ‏وَكَانَ يُعْرَفُ وَكَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا يُعْرَفُ فَكَانُوا يَقُولُونَ يَا ‏ ‏أَبَا بَكْرٍ ‏ ‏مَا هَذَا الْغُلَامُ بَيْنَ يَدَيْكَ قَالَ هَذَا يَهْدِينِي السَّبِيلَ فَلَمَّا دَنَوْا مِنْ ‏ ‏الْمَدِينَةِ ‏ ‏نَزَلَا ‏ ‏الْحَرَّةَ ‏ ‏وَبَعَثَا إِلَى ‏ ‏الْأَنْصَارِ ‏ ‏فَجَاءُوا فَقَالُوا قُومَا آمِنَيْنِ مُطَاعَيْنِ قَالَ فَشَهِدْتُهُ يَوْمَ دَخَلَ ‏ ‏الْمَدِينَةَ ‏ ‏فَمَا رَأَيْتُ يَوْمًا قَطُّ كَانَ أَحْسَنَ وَلَا ‏ ‏أَضْوَأَ مِنْ يَوْمٍ دَخَلَ عَلَيْنَا فِيهِ وَشَهِدْتُهُ يَوْمَ مَاتَ فَمَا رَأَيْتُ يَوْمًا كَانَ أَقْبَحَ وَلَا أَظْلَمَ مِنْ يَوْمٍ مَاتَ فِيهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏","","",""],[13551,13551,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏تَرَكَ قَتْلَى ‏ ‏بَدْرٍ ‏ ‏ثَلَاثَةَ أَيَّامٍ حَتَّى ‏ ‏جَيَّفُوا ‏ ‏ثُمَّ أَتَاهُمْ فَقَامَ عَلَيْهِمْ فَقَالَ يَا ‏ ‏أُمَيَّةُ بْنَ خَلَفٍ ‏ ‏يَا ‏ ‏أَبَا جَهْلِ بْنَ هِشَامٍ ‏ ‏يَا ‏ ‏عُتْبَةُ بْنَ رَبِيعَةَ ‏ ‏يَا ‏ ‏شَيْبَةُ بْنَ رَبِيعَةَ ‏ ‏هَلْ وَجَدْتُمْ مَا وَعَدَكُمْ رَبُّكُمْ حَقًّا فَإِنِّي قَدْ وَجَدْتُ مَا وَعَدَنِي رَبِّي حَقًّا قَالَ فَسَمِعَ ‏ ‏عُمَرُ ‏ ‏صَوْتَهُ فَقَالَ يَا رَسُولَ اللَّهِ ‏ ‏أَتُنَادِيهِمْ بَعْدَ ثَلَاثٍ وَهَلْ يَسْمَعُونَ يَقُولُ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏إِنَّكَ لَا تُسْمِعُ الْمَوْتَى ‏} ‏فَقَالَ وَالَّذِي نَفْسِي بِيَدِهِ مَا أَنْتُمْ بِأَسْمَعَ مِنْهُمْ وَلَكِنَّهُمْ لَا يَسْتَطِيعُونَ أَنْ يُجِيبُوا ‏","","",""],[13552,13552,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏أَبَا طَلْحَةَ ‏ ‏مَاتَ لَهُ ابْنٌ فَقَالَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏لَا تُخْبِرُوا ‏ ‏أَبَا طَلْحَةَ ‏ ‏حَتَّى أَكُونَ أَنَا الَّذِي أُخْبِرُهُ ‏ ‏فَسَجَّتْ ‏ ‏عَلَيْهِ فَلَمَّا جَاءَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏وَضَعَتْ بَيْنَ يَدَيْهِ طَعَامًا فَأَكَلَ ثُمَّ تَطَيَّبَتْ لَهُ فَأَصَابَ مِنْهَا ‏ ‏فَعَلِقَتْ ‏ ‏بِغُلَامٍ فَقَالَتْ يَا ‏ ‏أَبَا طَلْحَةَ ‏ ‏إِنَّ آلَ فُلَانٍ اسْتَعَارُوا مِنْ آلِ فُلَانٍ ‏ ‏عَارِيَةً ‏ ‏فَبَعَثُوا إِلَيْهِمْ ابْعَثُوا إِلَيْنَا بِعَارِيَتِنَا فَأَبَوْا أَنْ يَرُدُّوهَا فَقَالَ ‏ ‏أَبُو طَلْحَةَ ‏ ‏لَيْسَ لَهُمْ ذَلِكَ إِنَّ ‏ ‏الْعَارِيَةَ ‏ ‏مُؤَدَّاةٌ إِلَى أَهْلِهَا قَالَتْ فَإِنَّ ابْنَكَ كَانَ ‏ ‏عَارِيَةً ‏ ‏مِنْ اللَّهِ عَزَّ وَجَلَّ وَإِنَّ اللَّهَ عَزَّ وَجَلَّ قَدْ قَبَضَهُ ‏ ‏فَاسْتَرْجَعَ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏فَأُخْبِرَ ‏ ‏النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِذَلِكَ فَقَالَ ‏ ‏بَارَكَ اللَّهُ لَهُمَا فِي لَيْلَتِهِمَا قَالَ ‏ ‏فَعَلِقَتْ ‏ ‏بِغُلَامٍ فَوَلَدَتْ فَأَرْسَلَتْ بِهِ مَعِي ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏إِلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَحَمَلْتُ تَمْرًا فَأَتَيْتُ بِهِ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَعَلَيْهِ عَبَاءَةٌ وَهُوَ ‏ ‏يَهْنَأُ ‏ ‏بَعِيرًا لَهُ فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏هَلْ مَعَكَ تَمْرٌ قَالَ قُلْتُ نَعَمْ فَأَخَذَ التَّمَرَاتِ فَأَلْقَاهُنَّ فِي ‏ ‏فِيهِ ‏ ‏فَلَاكَهُنَّ ‏ ‏ثُمَّ جَمَعَ لُعَابَهُ ثُمَّ ‏ ‏فَغَرَ ‏ ‏فَاهُ ‏ ‏فَأَوْجَرَهُ ‏ ‏إِيَّاهُ فَجَعَلَ الصَّبِيُّ ‏ ‏يَتَلَمَّظُ ‏ ‏فَقَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏حُبُّ ‏ ‏الْأَنْصَارَ ‏ ‏التَّمْرَ ‏ ‏فَحَنَّكَهُ ‏ ‏وَسَمَّاهُ ‏ ‏عَبْدَ اللَّهِ ‏ ‏فَمَا كَانَ فِي ‏ ‏الْأَنْصَارِ ‏ ‏شَابٌّ أَفْضَلَ مِنْهُ ‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سَلَّامُ بْنُ مِسْكِينٍ ‏ ‏فَذَكَرَهُ ‏","","",""],[13553,13553,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏دَخَلَ عَلَى رَجُلٍ مِنْ أَصْحَابِهِ ‏ ‏يَعُودُهُ ‏ ‏وَقَدْ صَارَ كَالْفَرْخِ فَقَالَ لَهُ هَلْ سَأَلْتَ اللَّهَ عَزَّ وَجَلَّ قَالَ قُلْتُ اللَّهُمَّ مَا كُنْتَ مُعَاقِبِي بِهِ فِي الْآخِرَةِ فَعَجِّلْهُ فِي الدُّنْيَا فَقَالَ لَهُ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏لَا طَاقَةَ لَكَ بِعَذَابِ اللَّهِ هَلَّا قُلْتَ ‏ ‏اللَّهُمَّ رَبَّنَا آتِنَا فِي الدُّنْيَا حَسَنَةً وَفِي الْآخِرَةِ حَسَنَةً وَقِنَا عَذَابَ النَّارِ ‏","","",""],[13554,13554,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏أَصْحَابَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانُوا يَقُولُونَ وَهُمْ يَحْفِرُونَ ‏ ‏الْخَنْدَقَ ‏ ‏نَحْنُ الَّذِينَ ‏ ‏بَايَعُوا ‏ ‏مُحَمَّدًا ‏ ‏عَلَى الْإِسْلَامِ مَا بَقِينَا أَبَدًا ‏ ‏وَالنَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَقُولُ ‏ ‏اللَّهُمَّ إِنَّ الْخَيْرَ خَيْرُ ‏ ‏الْآخِرَهْ ‏ ‏فَاغْفِرْ ‏ ‏لِلْأَنْصَارِ ‏ ‏وَالْمُهَاجِرَهْ ‏ ‏فَأُتِيَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بِخُبْزِ شَعِيرٍ ‏ ‏وَإِهَالَةٍ ‏ ‏سَنِخَةٍ ‏ ‏فَأَكَلُوا مِنْهَا وَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا الْخَيْرُ خَيْرُ ‏ ‏الْآخِرَهْ ‏","","",""],[13555,13555,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَاهُ ‏ ‏جِبْرِيلُ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏وَهُوَ يَلْعَبُ مَعَ الْغِلْمَانِ فَأَخَذَهُ ‏ ‏فَصَرَعَهُ ‏ ‏فَشَقَّ عَنْ قَلْبِهِ فَاسْتَخْرَجَ مِنْهُ ‏ ‏عَلَقَةً ‏ ‏فَقَالَ هَذَا حَظُّ الشَّيْطَانِ مِنْكَ ثُمَّ غَسَلَهُ فِي ‏ ‏طَسْتٍ ‏ ‏مِنْ ذَهَبٍ بِمَاءِ ‏ ‏زَمْزَمَ ‏ ‏ثُمَّ ‏ ‏لَأَمَهُ ‏ ‏وَأَعَادَهُ فِي مَكَانِهِ وَجَاءَ الْغِلْمَانُ يَسْعَوْنَ إِلَى أُمِّهِ ‏ ‏يَعْنِي ‏ ‏ظِئْرِهِ ‏ ‏فَقَالُوا إِنَّ ‏ ‏مُحَمَّدًا ‏ ‏قَدْ قُتِلَ فَاسْتَقْبَلُوهُ وَهُوَ ‏ ‏مُنْتَقِعُ ‏ ‏اللَّوْنِ قَالَ لِي ‏ ‏أَنَسٌ ‏ ‏فَكُنْتُ أَرَى أَثَرَ الْمِخْيَطِ فِي صَدْرِهِ ‏ ‏وَرُبَّمَا قَالَ ‏ ‏حَمَّادٌ ‏ ‏إِنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَاهُ آتٍ ‏","","",""],[13556,13556,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏عَنْ ‏ ‏ثَابِتٍ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏ثَلَاثٌ مَنْ كُنَّ فِيهِ وَجَدَ حَلَاوَةَ الْإِيمَانِ مَنْ كَانَ اللَّهُ عَزَّ وَجَلَّ وَرَسُولُهُ أَحَبَّ إِلَيْهِ مِمَّا سِوَاهُمَا وَالرَّجُلُ يُحِبُّ الرَّجُلَ لَا يُحِبُّهُ إِلَّا لِلَّهِ وَالرَّجُلُ أَنْ يُقْذَفَ فِي النَّارِ أَحَبُّ إِلَيْهِ مِنْ أَنْ يَرْجِعَ يَهُودِيًّا أَوْ نَصْرَانِيًّا ‏","","",""],[13557,13557,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَدْخُلُ عَلَيْنَا وَكَانَ لِي أَخٌ صَغِيرٌ وَكَانَ لَهُ ‏ ‏نُغَيْرٌ ‏ ‏يَلْعَبُ بِهِ فَمَاتَ ‏ ‏نُغَرُهُ ‏ ‏الَّذِي كَانَ يَلْعَبُ بِهِ فَدَخَلَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ذَاتَ يَوْمٍ فَرَآهُ حَزِينًا فَقَالَ لَهُ مَا شَأْنُ ‏ ‏أَبِي عُمَيْرٍ ‏ ‏حَزِينًا فَقَالُوا مَاتَ ‏ ‏نُغَرُهُ ‏ ‏الَّذِي كَانَ يَلْعَبُ بِهِ يَا رَسُولَ اللَّهِ فَقَالَ ‏ ‏أَبَا عُمَيْرٍ ‏ ‏مَا فَعَلَ ‏ ‏النُّغَيْرُ ‏","","",""],[13558,13558,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ يَوْمَ ‏ ‏أُحُدٍ ‏ ‏وَهُوَ ‏ ‏يَسْلِتُ ‏ ‏الدِّمَاءَ عَنْ وَجْهِهِ كَيْفَ يُفْلِحُ قَوْمٌ ‏ ‏شَجُّوا ‏ ‏وَجْهَ نَبِيِّهِمْ وَكَسَرُوا ‏ ‏رَبَاعِيَتَهُ ‏ ‏وَهُوَ يَدْعُوهُمْ إِلَى اللَّهِ عَزَّ وَجَلَّ فَأَنْزَلَ اللَّهُ عَزَّ وَجَلَّ ‏ { ‏لَيْسَ لَكَ مِنْ الْأَمْرِ شَيْءٌ أَوْ يَتُوبَ عَلَيْهِمْ أَوْ يُعَذِّبَهُمْ فَإِنَّهُمْ ظَالِمُونَ ‏}","","",""],[13559,13559,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ‏ ‏رَجُلًا ‏ ‏سَأَلَ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَنْ قِيَامِ السَّاعَةِ وَأُقِيمَتْ الصَّلَاةُ فَلَمَّا قَضَى صَلَاتَهُ قَالَ أَيْنَ السَّائِلُ عَنْ السَّاعَةِ قَالَ الرَّجُلُ أَنَا يَا رَسُولَ اللَّهِ قَالَ ‏ ‏مَا أَعْدَدْتَ لَهَا فَإِنَّهَا قَائِمَةٌ قَالَ مَا أَعْدَدْتُ لَهَا كَثِيرَ عَمَلٍ غَيْرَ أَنِّي أُحِبُّ اللَّهَ وَرَسُولَهُ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَنْتَ مَعَ مَنْ أَحْبَبْتَ ‏ ‏قَالَ ‏ ‏فَمَا فَرِحَ الْمُسْلِمُونَ بِشَيْءٍ بَعْدَ الْإِسْلَامِ مَا فَرِحُوا بِهَذَا الْحَدِيثِ قَالَ فَكَانَ ‏ ‏أَنَسٌ ‏ ‏يَقُولُ فَنَحْنُ نُحِبُّ اللَّهَ وَرَسُولَهُ ‏","","",""],[13560,13560,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏إِسْحَاقُ بْنُ عَبْدِ اللَّهِ بْنِ أَبِي طَلْحَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏بَعَثَ خَالَهُ ‏ ‏حَرَامًا ‏ ‏أَخَا ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏فِي سَبْعِينَ إِلَى ‏ ‏بَنِي عَامِرٍ ‏ ‏فَلَمَّا قَدِمُوا قَالَ لَهُمْ خَالِي أَتَقَدَّمُكُمْ فَإِنْ أَمَّنُونِي حَتَّى أُبَلِّغَهُمْ عَنْ رَسُولِ اللَّهِ وَإِلَّا كُنْتُمْ مِنِّي قَرِيبًا قَالَ فَتَقَدَّمَ فَأَمَّنُوهُ فَبَيْنَمَا هُوَ يُحَدِّثُهُمْ عَنْ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِذْ ‏ ‏أَوْمَئُوا ‏ ‏إِلَى رَجُلٍ فَطَعَنَهُ فَأَنْفَذَهُ فَقَالَ اللَّهُ أَكْبَرُ فُزْتُ وَرَبِّ ‏ ‏الْكَعْبَةِ ‏ ‏ثُمَّ مَالُوا عَلَى بَقِيَّةِ أَصْحَابِهِ فَقَتَلُوهُمْ إِلَّا رَجُلًا أَعْرَجَ مِنْهُمْ كَانَ قَدْ صَعِدَ الْجَبَلَ ‏ ‏قَالَ ‏ ‏هَمَّامٌ ‏ ‏فَأُرَاهُ قَدْ ذَكَرَ مَعَ الْأَعْرَجِ آخَرَ مَعَهُ عَلَى الْجَبَلِ قَالَ وَحَدَّثَنَا ‏ ‏أَنَسٌ ‏ ‏أَنَّ ‏ ‏جِبْرِيلَ ‏ ‏عَلَيْهِ السَّلَام ‏ ‏أَتَى النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَخْبَرَهُ أَنَّهُمْ قَدْ لَقُوا رَبَّهُمْ فَرَضِيَ عَنْهُمْ وَأَرْضَاهُمْ قَالَ ‏ ‏أَنَسٌ ‏ ‏كَانُوا يَقْرَءُونَ أَنْ بَلِّغُوا قَوْمَنَا أَنَّا قَدْ لَقِينَا رَبَّنَا فَرَضِيَ عَنَّا وَأَرْضَانَا قَالَ ثُمَّ ‏ ‏نُسِخَ ‏ ‏بَعْدَ ذَلِكَ فَدَعَا عَلَيْهِمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏ثَلَاثِينَ صَبَاحًا عَلَى ‏ ‏رِعْلٍ ‏ ‏وَذَكْوَانَ ‏ ‏وَبَنِي لِحْيَانَ ‏ ‏وَعُصَيَّةَ ‏ ‏الَّذِينَ عَصَوْا اللَّهَ وَرَسُولَهُ ‏ ‏أَوْ عَصَوْا الرَّحْمَنَ ‏","","",""],[13561,13561,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏أَبَانُ بْنُ يَزِيدَ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ يَقُولُ ‏ ‏التَّفْلُ فِي الْمَسْجِدِ خَطِيئَةٌ وَكَفَّارَتُهُ دَفْنُهَا ‏","","",""],[13562,13562,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏جَرِيرٌ يَعْنِي ابْنَ حَازِمٍ ‏ ‏قَالَ سَمِعْتُ ‏ ‏قَتَادَةَ ‏ ‏قَالَ ‏ ‏قُلْتُ ‏ ‏لِأَنَسٍ ‏ ‏كَيْفَ كَانَتْ قِرَاءَةُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ كَانَ ‏ ‏يَمُدُّ صَوْتَهُ مَدًّا ‏","","",""],[13563,13563,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وحَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَبَا بَكْرٍ ‏ ‏وَعُمَرَ ‏ ‏وَعُثْمَانَ ‏ ‏كَانُوا ‏ ‏يَسْتَفْتِحُونَ الْقِرَاءَةَ بَعْدَ التَّكْبِيرِ بِ ‏ { ‏الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ ‏} ‏فِي الصَّلَاةِ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏يَعْنِي فِي الصَّلَاةِ بَعْدَ التَّكْبِيرِ ‏","","",""],[13564,13564,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ مِنْ ‏ ‏أَشْرَاطِ ‏ ‏السَّاعَةِ ‏ ‏قَالَ ‏ ‏هَمَّامٌ ‏ ‏وَرُبَّمَا قَالَ لَا تَقُومُ السَّاعَةُ ‏ ‏قَالَ ‏ ‏هَمَّامٌ ‏ ‏كِلَاهُمَا قَدْ سَمِعْتُ ‏ ‏حَتَّى ‏ ‏يُرْفَعَ ‏ ‏الْعِلْمُ وَيَظْهَرَ الْجَهْلُ وَتُشْرَبَ الْخَمْرُ وَيَظْهَرَ الزِّنَا وَيَقِلَّ الرِّجَالُ وَيَكْثُرَ النِّسَاءُ حَتَّى يَكُونَ لِخَمْسِينَ امْرَأَةً ‏ ‏الْقَيِّمُ ‏ ‏الْوَاحِدُ ‏","","",""],[13565,13565,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏بَيْنَمَا أَنَا أَسِيرُ فِي الْجَنَّةِ وَإِذَا أَنَا بِنَهَرٍ حَافَتَاهُ ‏ ‏قِبَابُ ‏ ‏الدُّرِّ ‏ ‏قَالَ قُلْتُ مَا هَذَا يَا ‏ ‏جِبْرِيلُ ‏ ‏قَالَ هَذَا الْكَوْثَرُ الَّذِي أَعْطَاكَ رَبُّكَ عَزَّ وَجَلَّ قَالَ فَضَرَبْتُ بِيَدِي فَإِذَا طِينُهُ ‏ ‏مِسْكٌ ‏ ‏أَذْفَرُ ‏","","",""],[13566,13566,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏نَهَى عَنْ ‏ ‏الْوِصَالِ ‏ ‏قَالَ قِيلَ لَهُ إِنَّكَ ‏ ‏تُوَاصِلُ ‏ ‏قَالَ إِنِّي أَبِيتُ يُطْعِمُنِي رَبِّي وَيَسْقِينِي ‏","","",""],[13567,13567,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ عِنْدَ ‏ ‏الزَّوَالِ ‏ ‏فَاحْتَاجَ أَصْحَابُهُ إِلَى الْوُضُوءِ قَالَ ‏ ‏فَجِيءَ ‏ ‏بِقَعْبٍ ‏ ‏فِيهِ مَاءٌ يَسِيرٌ فَوَضَعَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَفَّهُ فِيهِ فَجَعَلَ يَنْبُعُ مِنْ بَيْنِ أَصَابِعِهِ حَتَّى تَوَضَّأَ الْقَوْمُ كُلُّهُمْ ‏ ‏قُلْتُ كَمْ كُنْتُمْ ‏ ‏قَالَ ‏ ‏زُهَاءَ ‏ ‏ثَلَاثِ مِائَةٍ ‏","","",""],[13568,13568,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏لَا يُؤْمِنُ عَبْدٌ حَتَّى يُحِبَّ لِأَخِيهِ مَا يُحِبُّ لِنَفْسِهِ مِنْ الْخَيْرِ ‏","","",""],[13569,13569,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا مِنْ أَهْلِ الْجَنَّةِ أَحَدٌ يَسُرُّهُ أَنْ يَرْجِعَ إِلَى الدُّنْيَا وَلَهُ عَشَرَةُ أَمْثَالِهَا إِلَّا الشَّهِيدَ فَإِنَّهُ يَوَدُّ أَنَّهُ يَرْجِعُ إِلَى الدُّنْيَا فَاسْتُشْهِدَ عَشْرَ مَرَّاتٍ لِمَا رَأَى مِنْ الْفَضْلِ ‏","","",""],[13570,13570,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ يَهُودِيًّا مَرَّ عَلَى النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابِهِ فَقَالَ ‏ ‏السَّامُ ‏ ‏عَلَيْكُمْ فَرَدَّ عَلَيْهِ ‏ ‏أَصْحَابُ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِنَّمَا قَالَ ‏ ‏السَّامُ ‏ ‏عَلَيْكُمْ فَأُخِذَ الْيَهُودِيُّ فَجِيءَ بِهِ فَاعْتَرَفَ قَالَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏رُدُّوا عَلَيْهِمْ مَا قَالُوا ‏","","",""],[13571,13571,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏أَتَيْتُ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَقَدْ دَعَاهُ خَيَّاطٌ مِنْ أَهْلِ ‏ ‏الْمَدِينَةِ ‏ ‏فَإِذَا ‏ ‏خُبْزُ شَعِيرٍ ‏ ‏وَإِهَالَةٌ ‏ ‏سَنِخَةٌ ‏ ‏قَالَ فَإِذَا فِيهَا قَرْعٌ قَالَ وَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْجِبُهُ الْقَرْعُ قَالَ فَجَعَلْتُ أُقَرِّبُهُ قُدَّامَ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏أَنَسٌ ‏ ‏لَمْ أَزَلْ يُعْجِبُنِي الْقَرْعُ مُنْذُ رَأَيْتُ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُعْجِبُهُ ‏","","",""],[13572,13572,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏وَحَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏قَالَا حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ ‏ ‏عَفَّانُ ‏ ‏فِي حَدِيثِهِ ‏ ‏أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏قَالَ حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏وَقَالَ ‏ ‏بَهْزٌ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ ‏ ‏رَهْطًا ‏ ‏مِنْ ‏ ‏عُرَيْنَةَ ‏ ‏أَتَوْا رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالُوا إِنَّا قَدْ ‏ ‏اجْتَوَيْنَا ‏ ‏الْمَدِينَةَ ‏ ‏فَعَظُمَتْ بُطُونُنَا وَانْتَهَشَتْ أَعْضَاؤُنَا ‏ ‏فَأَمَرَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَلْحَقُوا بِرَاعِي الْإِبِلِ فَيَشْرَبُوا مِنْ أَلْبَانِهَا وَأَبْوَالِهَا قَالَ فَلَحِقُوا بِرَاعِي الْإِبِلِ فَشَرِبُوا مِنْ أَلْبَانِهَا وَأَبْوَالِهَا حَتَّى صَلُحَتْ بُطُونُهُمْ وَأَلْوَانُهُمْ ثُمَّ قَتَلُوا ‏ ‏الرَّاعِي ‏ ‏وَسَاقُوا الْإِبِلَ فَبَلَغَ ذَلِكَ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَبَعَثَ فِي طَلَبِهِمْ فَجِيءَ بِهِمْ فَقَطَعَ أَيْدِيَهُمْ وَأَرْجُلَهُمْ ‏ ‏وَسَمَرَ ‏ ‏أَعْيُنَهُمْ ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏مُحَمَّدِ بْنِ سِيرِينَ ‏ ‏إِنَّمَا كَانَ هَذَا قَبْلَ أَنْ تَنْزِلَ ‏ ‏الْحُدُودُ ‏","","",""],[13573,13573,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْوَاحِدِ ‏ ‏حَدَّثَنَا ‏ ‏الْمُخْتَارُ بْنُ فُلْفُلٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏صَلَّى رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏صَلَاةً فَأَقْبَلَ عَلَيْنَا بِوَجْهِهِ فَقَالَ ‏ ‏إِنِّي إِمَامُكُمْ فَلَا تَسْبِقُونِي بِالرُّكُوعِ وَلَا بِالسُّجُودِ وَلَا بِالْقِيَامِ فَإِنِّي أَرَاكُمْ مِنْ بَيْنِ يَدَيَّ وَمِنْ خَلْفِي قَالَ ثُمَّ قَالَ وَالَّذِي نَفْسِي بِيَدِهِ لَوْ رَأَيْتُمْ مَا رَأَيْتُ لَضَحِكْتُمْ قَلِيلًا وَلَبَكَيْتُمْ كَثِيرًا قَالُوا يَا رَسُولَ اللَّهِ وَمَا رَأَيْتَ قَالَ رَأَيْتُ الْجَنَّةَ وَالنَّارَ ‏","","",""],[13574,13574,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏سُلَيْمَانُ بْنُ الْمُغِيرَةِ ‏ ‏حَدَّثَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏مَاتَ ابْنٌ ‏ ‏لِأَبِي طَلْحَةَ ‏ ‏مِنْ ‏ ‏أُمِّ سُلَيْمٍ ‏ ‏قَالَ فَقَالَتْ ‏ ‏أُمُّ سُلَيْمٍ ‏ ‏لِأَهْلِهَا لَا تُحَدِّثُوا ‏ ‏أَبَا طَلْحَةَ ‏ ‏بِابْنِهِ حَتَّى أَكُونَ أَنَا أُحَدِّثُهُ ‏ ‏فَذَكَرَ مَعْنَى حَدِيثِ ‏ ‏بَهْزٍ ‏ ‏إِلَّا أَنَّهُ قَالَ ‏ ‏قَالَتْ أُمِّي يَا ‏ ‏أَنَسُ ‏ ‏لَا يُطْعَمْ شَيْئًا حَتَّى ‏ ‏تَغْدُوَ ‏ ‏بِهِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ فَبَاتَ يَبْكِي وَبِتُّ ‏ ‏مُجْتَنِحًا ‏ ‏عَلَيْهِ ‏ ‏أُكَالِئُهُ ‏ ‏حَتَّى أَصْبَحْتُ ‏ ‏فَغَدَوْتُ ‏ ‏بِهِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَإِذَا مَعَهُ ‏ ‏مِيسَمٌ ‏ ‏فَلَمَّا رَأَى الصَّبِيَّ مَعِي قَالَ ‏ ‏لَعَلَّ ‏ ‏أُمَّ سُلَيْمٍ ‏ ‏وَلَدَتْ قَالَ قُلْتُ نَعَمْ فَوَضَعَ ‏ ‏الْمِيسَمَ ‏ ‏مِنْ يَدِهِ وَقَعَدَ ‏","","",""],[13575,13575,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ إِذَا أَكَلَ طَعَامًا لَعِقَ أَصَابِعَهُ الثَّلَاثَ وَقَالَ ‏ ‏إِذَا وَقَعَتْ لُقْمَةُ أَحَدِكُمْ ‏ ‏فَلْيُمِطْ ‏ ‏عَنْهَا الْأَذَى وَلْيَأْكُلْهَا وَلَا يَدَعْهَا لِلشَّيْطَانِ وَأَمَرَنَا أَنْ ‏ ‏نَسْلِتَ ‏ ‏الصَّحْفَةَ وَقَالَ إِنَّكُمْ لَا تَدْرُونَ فِي أَيِّ طَعَامِكُمْ الْبَرَكَةَ ‏","","",""],[13576,13576,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثَابِتٌ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ ثَمَانِينَ رَجُلًا مِنْ أَهْلِ ‏ ‏مَكَّةَ ‏ ‏هَبَطُوا عَلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَأَصْحَابِهِ مِنْ ‏ ‏جَبَلِ التَّنْعِيمِ ‏ ‏عِنْدَ صَلَاةِ الْفَجْرِ فَأَخَذَهُمْ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سِلْمًا فَعَفَا عَنْهُمْ وَنَزَلَ الْقُرْآنُ ‏ { ‏وَهُوَ الَّذِي ‏ ‏كَفَّ ‏ ‏أَيْدِيَهُمْ عَنْكُمْ وَأَيْدِيَكُمْ عَنْهُمْ بِبَطْنِ ‏ ‏مَكَّةَ ‏ ‏مِنْ بَعْدِ أَنْ ‏ ‏أَظْفَرَكُمْ ‏ ‏عَلَيْهِمْ ‏}","","",""],[13577,13577,"","","‏ ‏حَدَّثَنَا ‏ ‏عَفَّانُ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏عَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏اتَّخَذَ خَاتَمًا وَنَقَشَ فِيهِ نَقْشًا فَقَالَ إِنِّي اتَّخَذْتُ خَاتَمًا وَنَقَشْتُ فِيهِ نَقْشًا فَلَا يَنْقُشْ أَحَدٌ عَلَى نَقْشِهِ ‏","","",""],[13578,13578,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏قَالَ ‏ ‏كَانَ النَّبِيُّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُحِبُّ الْقَرْعَ ‏ ‏أَوْ قَالَ ‏ ‏الدُّبَّاءَ ‏ ‏قَالَ فَرَأَيْتُهُ يَوْمًا يَأْكُلُهُ فَجَعَلْتُ أَضَعُهُ بَيْنَ يَدَيْهِ ‏","","",""],[13579,13579,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ اللَّهِ بْنُ عَبْدِ اللَّهِ بْنِ جَبْرٍ ‏ ‏أَنَّهُ سَمِعَ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يَقُولُ ‏ ‏كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْتَسِلُ بِخَمْسَةِ ‏ ‏مَكَاكِيكَ ‏ ‏وَيَتَوَضَّأُ ‏ ‏بِمَكُّوكٍ ‏","","",""],[13580,13580,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏قَتَادَةُ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏يُحَدِّثُ عَنْ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏مَا بَعَثَ اللَّهُ عَزَّ وَجَلَّ نَبِيًّا إِلَّا أَنْذَرَ أُمَّتَهُ ‏ ‏الدَّجَّالَ ‏ ‏أَلَا إِنَّهُ الْأَعْوَرُ الْكَذَّابُ أَلَا إِنَّهُ أَعْوَرُ وَإِنَّ رَبَّكُمْ لَيْسَ بِأَعْوَرَ مَكْتُوبٌ بَيْنَ عَيْنَيْهِ كَفَرَ ‏","","",""],[13581,13581,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏أَخْبَرَنِي ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّهُمْ قَالُوا يَا رَسُولَ اللَّهِ ‏ ‏أَهْلُ الْكِتَابِ ‏ ‏إِذَا سَلَّمُوا عَلَيْنَا كَيْفَ نَرُدُّ عَلَيْهِمْ قَالَ ‏ ‏قُولُوا وَعَلَيْكُمْ ‏","","",""],[13582,13582,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏سَوُّوا صُفُوفَكُمْ فَإِنَّ تَسْوِيَةَ الصُّفُوفِ مِنْ تَمَامِ الصَّلَاةِ ‏","","",""],[13583,13583,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏اعْتَدِلُوا فِي السُّجُودِ وَلَا يَبْسُطْ أَحَدُكُمْ ذِرَاعَيْهِ كَمَا يَبْسُطُ الْكَلْبُ ‏","","",""],[13584,13584,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَتَى عَلَى رَجُلٍ يَسُوقُ ‏ ‏بَدَنَةً ‏ ‏قَالَ ‏ ‏ارْكَبْهَا قَالَ إِنَّهَا ‏ ‏بَدَنَةٌ ‏ ‏قَالَ ارْكَبْهَا قَالَ إِنَّهَا ‏ ‏بَدَنَةٌ ‏ ‏قَالَ ‏ ‏وَيْحَكَ ‏ ‏أَوْ وَيْلَكَ ‏ ‏ارْكَبْهَا ‏","","",""],[13585,13585,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِذَا كَانَ أَحَدُكُمْ فِي صَلَاتِهِ فَإِنَّهُ ‏ ‏يُنَاجِي ‏ ‏رَبَّهُ عَزَّ وَجَلَّ فَلَا يَتْفُلَنَّ بَيْنَ يَدَيْهِ وَلَا عَنْ يَمِينِهِ وَلْيَتْفُلْ عَنْ يَسَارِهِ تَحْتَ قَدَمِهِ ‏","","",""],[13586,13586,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَتْ ‏ ‏بِالْمَدِينَةِ ‏ ‏فَزْعَةٌ ‏ ‏فَاسْتَعَارَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَرَسًا ‏ ‏لِأَبِي طَلْحَةَ ‏ ‏يُقَالُ لَهُ مَنْدُوبٌ فَرَكِبَهُ وَقَالَ ‏ ‏مَا رَأَيْنَا مِنْ ‏ ‏فَزَعٍ ‏ ‏وَإِنْ وَجَدْنَاهُ ‏ ‏لَبَحْرًا ‏","","",""],[13587,13587,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏شُعْبَةُ ‏ ‏قَالَ أَخْبَرَنِي ‏ ‏أَنَسُ بْنُ سِيرِينَ ‏ ‏قَالَ سَمِعْتُ ‏ ‏أَنَسَ بْنَ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ رَجُلٌ مِنْ ‏ ‏الْأَنْصَارِ ‏ ‏ضَخْمًا لَا يَسْتَطِيعُ أَنْ يُصَلِّيَ مَعَ النَّبِيِّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَقَالَ يَا رَسُولَ اللَّهِ إِنِّي لَا أَسْتَطِيعُ أَنْ أُصَلِّيَ مَعَكَ فَصَنَعَ لَهُ طَعَامًا وَدَعَا النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏إِلَيْهِ ‏ ‏وَبَسَطُوا ‏ ‏لَهُ حَصِيرًا وَنَضَحُوهُ ‏ ‏فَصَلَّى عَلَيْهِ رَكْعَتَيْنِ فَقَالَ لَهُ رَجُلٌ مِنْ آلِ ‏ ‏الْجَارُودِ ‏ ‏أَكَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يُصَلِّي الضُّحَى قَالَ مَا رَأَيْتُهُ صَلَّاهَا إِلَّا يَوْمَئِذٍ ‏","","",""],[13588,13588,"","","‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏ثُمَامَةُ بْنُ عَبْدِ اللَّهِ بْنِ أَنَسٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏جَاءَهُ أَصْحَابُهُ ذَاتَ لَيْلَةٍ فَخَرَجَ فَصَلَّى بِهِمْ فَخَفَّفَ ثُمَّ دَخَلَ بَيْتَهُ فَأَطَالَ ثُمَّ خَرَجَ فَصَلَّى بِهِمْ فَخَفَّفَ ثُمَّ دَخَلَ بَيْتَهُ فَأَطَالَ فَلَمَّا أَصْبَحَ قَالُوا يَا رَسُولَ اللَّهِ صَلَّيْتَ فَجَعَلْتَ تُطِيلُ إِذَا دَخَلْتَ وَتُخَفِّفُ إِذَا خَرَجْتَ قَالَ ‏ ‏مِنْ أَجْلِكُمْ فَعَلْتُ مَا فَعَلْتُ ‏","","",""],[13589,13589,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ يَعْنِي ابْنَ سَلَمَةَ ‏ ‏قَالَ أَخْبَرَنَا ‏ ‏شُعَيْبُ بْنُ الْحَبْحَابِ ‏ ‏وَعَبْدُ الْعَزِيزِ بْنُ صُهَيْبٍ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْتَقَ ‏ ‏صَفِيَّةَ ‏ ‏وَجَعَلَ عِتْقَهَا ‏ ‏صَدَاقَهَا ‏","","",""],[13590,13590,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏حَدَّثَنَا ‏ ‏قَتَادَةُ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَعْتَقَ ‏ ‏صَفِيَّةَ ‏ ‏وَجَعَلَ عِتْقَهَا ‏ ‏صَدَاقَهَا ‏","","",""],[13591,13591,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏هَمَّامٌ ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ رَسُولَ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏زَجَرَ ‏ ‏عَنْ الشُّرْبِ قَائِمًا ‏ ‏قَالَ ‏ ‏قَتَادَةُ ‏ ‏فَسَأَلْنَا ‏ ‏أَنَسًا ‏ ‏عَنْ الْأَكْلِ قَالَ ‏ ‏الْأَكْلُ أَشَدُّ ‏","","",""],[13592,13592,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏بَهْزٌ ‏ ‏حَدَّثَنَا ‏ ‏حَمَّادٌ ‏ ‏حَدَّثَنَا ‏ ‏هِشَامُ بْنُ زَيْدٍ ‏ ‏عَنْ ‏ ‏جَدِّهِ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كُنْتُ غُلَامًا ‏ ‏جَوَادًا ‏ ‏فَصِدْتُ أَرْنَبًا فَشَوَيْنَاهَا ‏ ‏فَأَرْسَلَ مَعِي ‏ ‏أَبُو طَلْحَةَ ‏ ‏بِعَجُزِهَا ‏ ‏إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏فَأَتَيْتُهُ بِهَا ‏","","",""],[13593,13593,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنَا ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏يُقَالُ لِلْكَافِرِ يَوْمَ الْقِيَامَةِ أَرَأَيْتَ لَوْ كَانَ لَكَ مِلْءُ الْأَرْضِ ذَهَبًا أَكُنْتَ ‏ ‏تَفْتَدِي ‏ ‏بِهِ فَيَقُولُ نَعَمْ قَالَ يُقَالُ لَهُ قَدْ سُئِلْتَ أَيْسَرَ مِنْ ذَلِكَ ‏","","",""],[13594,13594,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏قَالَ ‏ ‏كَانَ ‏ ‏أَحَبَّ الثِّيَابِ إِلَى رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَنْ يَلْبَسَهَا ‏ ‏الْحِبَرَةُ ‏","","",""],[13595,13595,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏ثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏كَانَ ‏ ‏يَدُورُ عَلَى نِسَائِهِ فِي السَّاعَةِ الْوَاحِدَةِ مِنْ اللَّيْلِ وَالنَّهَارِ وَهُنَّ إِحْدَى عَشْرَةَ قَالَ قُلْتُ ‏ ‏لِأَنَسٍ ‏ ‏هَلْ كَانَ يُطِيقُ ذَلِكَ قَالَ كُنَّا نَتَحَدَّثُ أَنَّهُ أُعْطِيَ قُوَّةَ ثَلَاثِينَ ‏","","",""],[13596,13596,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذٌ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏عَنْ ‏ ‏أَنَسِ بْنِ مَالِكٍ ‏ ‏أَنَّ النَّبِيَّ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏وَجَدَ تَمْرَةً فَقَالَ ‏ ‏لَوْلَا أَنِّي أَخَافُ أَنْ تَكُونَ ‏ ‏صَدَقَةً ‏ ‏لَأَكَلْتُهَا ‏","","",""],[13597,13597,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْد اللَّهِ ‏ ‏حَدَّثَنِي ‏ ‏أَبِي ‏ ‏حَدَّثَنَا ‏ ‏عَلِيُّ بْنُ عَبْدِ اللَّهِ ‏ ‏حَدَّثَنَا ‏ ‏مُعَاذُ بْنُ هِشَامٍ ‏ ‏قَالَ حَدَّثَنِي ‏ ‏أَبِي ‏ ‏عَنْ ‏ ‏قَتَادَةَ ‏ ‏حَدَّثَنَا ‏ ‏أَنَسُ بْنُ مَالِكٍ ‏ ‏أَنَّ نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏قَالَ ‏ ‏إِنَّ لِكُلِّ نَبِيٍّ دَعْوَةً وَإِنِّي اخْتَبَأْتُ دَعْوَتِي شَفَاعَةً لِأُمَّتِي يَوْمَ الْقِيَامَةِ ‏","","",""],[13598,13598,"","","‏ ‏حَدَّثَنَا ‏ ‏أَبُو بَكْرٍ أَحْمَدُ بْنُ جَعْفَرِ بْنِ حَمْدَانَ بْنِ مَالِكٍ الْقُطَيعِيُّ ‏ ‏حَدَّثَنَا ‏ ‏أَبُو عَامِرٍ عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏زُهَيْرٌ ‏ ‏عَنْ ‏ ‏زَيْدٍ يَعْنِي ابْنَ أَسْلَمَ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمَا ‏ ‏قَالَ ‏ ‏أَشْرَفَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏عَلَى ‏ ‏فَلَقٍ ‏ ‏مِنْ ‏ ‏أَفْلَاقِ ‏ ‏الْحَرَّةِ ‏ ‏وَنَحْنُ مَعَهُ فَقَالَ ‏ ‏نِعْمَتِ الْأَرْضُ ‏ ‏الْمَدِينَةُ ‏ ‏إِذَا خَرَجَ ‏ ‏الدَّجَّالُ ‏ ‏عَلَى كُلِّ ‏ ‏نَقْبٍ ‏ ‏مِنْ ‏ ‏أَنْقَابِهَا ‏ ‏مَلَكٌ لَا يَدْخُلُهَا فَإِذَا كَانَ كَذَلِكَ رَجَفَتْ ‏ ‏الْمَدِينَةُ ‏ ‏بِأَهْلِهَا ثَلَاثَ رَجَفَاتٍ لَا يَبْقَى مُنَافِقٌ وَلَا مُنَافِقَةٌ إِلَّا خَرَجَ إِلَيْهِ وَأَكْثَرُ ‏ ‏يَعْنِي مَنْ يَخْرُجُ إِلَيْهِ النِّسَاءُ ‏ ‏وَذَلِكَ يَوْمُ التَّخْلِيصِ وَذَلِكَ يَوْمَ ‏ ‏تَنْفِي ‏ ‏الْمَدِينَةُ ‏ ‏الْخَبَثَ كَمَا يَنْفِي ‏ ‏الْكِيرُ ‏ ‏خَبَثَ الْحَدِيدِ يَكُونُ مَعَهُ سَبْعُونَ أَلْفًا مِنْ ‏ ‏الْيَهُودِ ‏ ‏عَلَى كُلِّ رَجُلٍ مِنْهُمْ ‏ ‏سَاجٌ ‏ ‏وَسَيْفٌ مُحَلًّى فَتُضْرَبُ رَقَبَتُهُ بِهَذَا الضَّرْبِ الَّذِي عِنْدَ مُجْتَمَعِ السُّيُولِ ثُمَّ قَالَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏مَا كَانَتْ ‏ ‏فِتْنَةٌ ‏ ‏وَلَا تَكُونُ حَتَّى تَقُومَ السَّاعَةُ أَكْبَرَ مِنْ ‏ ‏فِتْنَةِ ‏ ‏الدَّجَّالِ ‏ ‏وَلَا مِنْ نَبِيٍّ إِلَّا وَقَدْ حَذَّرَ أُمَّتَهُ وَلَأُخْبِرَنَّكُمْ بِشَيْءٍ مَا أَخْبَرَهُ نَبِيٌّ أُمَّتَهُ قَبْلِي ثُمَّ وَضَعَ يَدَهُ عَلَى عَيْنِهِ ثُمَّ قَالَ أَشْهَدُ أَنَّ اللَّهَ عَزَّ وَجَلَّ لَيْسَ بِأَعْوَرَ ‏","","",""],[13599,13599,"","","‏ ‏حَدَّثَنَا ‏ ‏عَبْدُ الْمَلِكِ بْنُ عَمْرٍو ‏ ‏حَدَّثَنَا ‏ ‏هِشَامٌ يَعْنِي ابْنَ سَعْدٍ ‏ ‏عَنْ ‏ ‏زَيْدِ بْنِ أَسْلَمَ ‏ ‏عَنْ ‏ ‏عُبَيْدِ اللَّهِ بْنِ مِقْسَمٍ ‏ ‏قَالَ ‏ ‏سَأَلَ ‏ ‏الْحَسَنُ بْنُ مُحَمَّدٍ ‏ ‏جَابِرَ بْنَ عَبْدِ اللَّهِ ‏ ‏رَضِيَ اللَّهُ تَعَالَى عَنْهُمَا ‏ ‏عَنْ الْغُسْلِ مِنْ الْجَنَابَةِ فَقَالَ تَبُلُّ الشَّعْرَ وَتَغْسِلُ الْبَشَرَةَ قَالَ فَكَيْفَ كَانَ رَسُولُ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَغْتَسِلُ قَالَ كَانَ ‏ ‏يَصُبُّ عَلَى رَأْسِهِ ثَلَاثًا قَالَ إِنَّ رَأْسِي كَثِيرُ الشَّعْرِ قَالَ كَانَ رَأْسُ رَسُولِ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏أَكْثَرَ مِنْ رَأْسِكَ وَأَطْيَبَ ‏","","",""],[13600,13600,"","","‏ ‏حَدَّثَنَا ‏ ‏يَحْيَى بْنُ حَمَّادٍ ‏ ‏أَخْبَرَنَا ‏ ‏أَبُو عَوَانَةَ ‏ ‏عَنْ ‏ ‏أَبِي بِشْرٍ ‏ ‏عَنْ ‏ ‏سُلَيْمَانَ بْنِ قَيْسٍ ‏ ‏عَنْ ‏ ‏جَابِرِ بْنِ عَبْدِ اللَّهِ ‏ ‏رَضِيَ اللَّهُ عَنْهُمَا ‏ ‏قَالَ ‏ ‏بَايَعْنَا نَبِيَّ اللَّهِ ‏ ‏صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ‏ ‏يَوْمَ ‏ ‏الْحُدَيْبِيَةِ ‏ ‏عَلَى أَنْ لَا ‏ ‏نَفِرَّ ‏","","",""]];
